'use strict';

function readingReferenceList(references = []) {
  if (!references.length) return '';
  return `<details class="history-sources"><summary>补充正文的资料依据 ＋</summary>${references.map(ref =>
    `<p>${/^https:\/\//.test(ref.url || '') ? `<a href="${E(ref.url)}" target="_blank" rel="noopener noreferrer">${E(ref.label)} ↗</a>` : E(ref.label)}${ref.note ? `<small> · ${E(ref.note)}</small>` : ''}</p>`
  ).join('')}</details>`;
}

function readingParagraphs(paragraphs) {
  return paragraphs.map(paragraph => `<p>${E(paragraph)}</p>`).join('');
}

function readingEntry(x) {
  return window.HISTORY_READING_DEPTH?.[x.id];
}

function readingDepth(x) {
  const entry = readingEntry(x);
  if (!entry) return '';
  return `<section class="narrative-section"><h3>${E(entry.heading || (x.name ? '生平详读' : '来龙去脉'))}</h3>${readingParagraphs(entry.paragraphs)}${readingReferenceList(entry.references)}${entry.ruler ? `<p><a href="rulers/index.html?v=0.20.0#regime/${E(entry.ruler.regimeId)}/${E(entry.ruler.id)}">打开统治者档案，查看生卒和在位阶段 ↗</a></p>` : ''}${entry.battle ? `<p><a href="battles/index.html#battle/${E(entry.battle)}">进入战役专题 ↗</a></p>` : ''}</section>`;
}

// Only use direct event–person associations and the editors' explicit topic links.
// Related narratives remain labelled as context, since association alone does not imply causation.
function readingContext(x, isWorld) {
  const isPerson = Boolean(x.name);
  const stories = isWorld || typeof B === 'undefined' ? [] : B.stories.filter(story =>
    isPerson ? story.peopleProfiles.some(profile => bookPersonID(profile.name) === x.id)
      : story.eventIds.includes(x.id)
  ).slice(0, 1);
  const book = stories.map(story => {
    const paragraphs = isPerson
      ? story.peopleProfiles.filter(profile => bookPersonID(profile.name) === x.id).flatMap(profile => [profile.context, profile.choice, profile.limit])
      : [story.intro, ...story.scenes.map(scene => scene.body)];
    return `<details class="history-sources"><summary>史书专题 · ${E(story.title)} ＋</summary>${readingParagraphs(paragraphs.filter(Boolean))}${historyBookRefs(story.sourceRefs)}</details>`;
  }).join('');
  const related = isPerson
    ? (x.eventIds || []).map(id => by(isWorld ? 'worldEvents' : 'events', id)).filter(Boolean)
    : (x.personIds || []).map(id => by('people', id)).filter(Boolean).filter(person => person.entryKind !== 'person-thread');
  const frames = isWorld
    ? (x.worldEntryIds || []).map(id => by('worldEntries', id)).filter(Boolean).slice(0, 1)
    : [];
  const eventGroup = isWorld ? 'worldEvents' : 'events';
  const otherEvents = isPerson ? [] : [...new Set((x.personIds || [])
    .flatMap(id => by('people', id)?.eventIds || []))]
    .map(id => by(eventGroup, id))
    .filter(item => item && item.id !== x.id && item.title !== x.title)
    .sort((a, b) => Math.abs((a.start ?? x.start) - x.start) - Math.abs((b.start ?? x.start) - x.start))
    .slice(0, 3);
  const frameEvents = isWorld && !isPerson && !x.worldEntryIds
    ? D.worldEvents.filter(event => event.worldEntryIds?.includes(x.id)).slice(0, 3)
    : [];
  const candidates = [...related, ...frames, ...otherEvents, ...frameEvents].filter(item => item.id !== x.id);
  const current = [x.summary, x.importance, x.outcome, x.description, x.contribution, x.context, ...(readingEntry(x)?.paragraphs || [])].filter(Boolean).join('');
  const seen = new Set();
  const snippets = candidates.map(item => {
    const paragraphs = [item.summary || item.description, item.outcome || item.contribution]
      .filter(value => value && value.length >= 24 && !current.includes(value) && !seen.has(value));
    paragraphs.forEach(value => seen.add(value));
    return { item, paragraphs };
  }).filter(row => row.paragraphs.length).slice(0, 3);
  if (!book && !snippets.length) return '';
  return `<section class="narrative-section"><h3>连读相关史事与人物</h3>${book}${snippets.map(({item, paragraphs}, index) => {
    const type = item.name ? 'person' : frames.includes(item) ? 'world' : isWorld ? 'world-event' : 'event';
    return `<details class="history-sources"${index === 0 && !readingEntry(x) && !narrativeRecord(x) ? ' open' : ''}><summary>${E(item.title || item.name)} ＋</summary>${item.start != null ? `<p class="caption">${E(date(item))}</p>` : ''}${readingParagraphs(paragraphs)}${historySources(item)}<button class="history-return" data-${type}="${E(item.id)}">打开完整条目 →</button></details>`;
  }).join('')}</section>`;
}
// Reading records generated from the edited manuscripts and existing site archives.
window.HISTORY_READING_DEPTH = {
  "v5-xia-shaokang": {"paragraphs":["《左传·哀公元年》借伍员劝吴王提防越国，回述夏后氏一度丧失权力、少康重建政权的故事。这里的重点是一个暂时弱小的对手可能依靠长期经营重新崛起。故事把少康写成依托有虞、在纶地获得土地和部众，再联络夏的旧臣、瓦解寒浞一系的人物。","把《左传》的故事同《史记·夏本纪》的简短世系相比较，可以发现各书详略和编排不同。传说提供的是先秦人如何理解流亡、结盟与王统延续的材料。具体战场、年数和人物关系无法逐项对照同时代记录，也不能直接用来解释二里头某一层文化遗存的变化。"],"references":[{"label":"王玉哲《中华远古史》第四章第二节"},{"label":"《左传·哀公元年》"}]},
  "cn-fuhao": {"paragraphs":["殷墟妇好墓1976年发掘于小屯一带，墓内出土成组礼器、兵器、玉器和骨器。若把一件觚或爵放回整组礼器中看，器形、铭文和器物组合能帮助识别供奉对象以及礼仪如何安排。多件铜器带有妇好或与祭祀称谓相关的铭文，为墓主辨认提供了物证。","墓葬与卜辞可以互相参照。卜辞让人看到妇好参与祭祀、征伐等王室事务，墓中成组的器物则显示王室能够调动青铜铸造、玉料加工和礼仪供给。兵器的存在本身不足以重建某一战役，器物的材质与工艺也各有自己的来源和流通问题。"],"references":[{"label":"胡厚宣、胡振宇《殷商史》工艺美术篇"},{"label":"中国社会科学院考古研究所《殷墟妇好墓》发掘报告"}]},
  "v5-zhou-luoyi": {"paragraphs":["周初平定东方的反抗后，需要在靠近原商王畿和东方诸侯的地方组织军政。洛邑的经营改变了王朝从关中向东发令的条件。传世《召诰》《洛诰》保留了相宅、营建和安排政务的叙述，《多士》则显示如何对待迁居新邑的殷遗民，是营建所伴随的政治问题。","何尊铭文保存了成周与王权经营中原有关的记忆，可同传世篇章对读。洛邑的意义在于使周王室在东方有可驻节和动员的据点，丰镐仍承担王朝西部的政治职能。成周的范围、营建阶段与相关地名的对应，需要结合铭文、传世书和发掘材料分别讨论。"],"references":[{"label":"杨宽《西周史》第一编"},{"label":"《尚书·召诰》《洛诰》"},{"label":"何尊铭文"}]},
  "v5-eastern-three-jin": {"paragraphs":["晋国原是春秋强国，但作战、征税和领地经营逐渐由强大的卿族掌握。到春秋晚期，卿族间的战争已能直接改变晋国内部的势力分配。韩、赵、魏联合击败智氏并分享其土地后，各自在控制区继续扩张，晋君能够直接支配的力量日益缩小。","前403年周王承认三家为诸侯，给已经形成的权力格局加上新的名分。晋国残余又延续了一段时间，因此三家分晋既可以指长期的权力转移，也可用来标示获得封爵的节点。魏、赵、韩随后沿不同方向经营，旧晋所覆盖的战略空间成为战国列国争夺的核心之一。"],"references":[{"label":"杨宽《战国史》第七章"},{"label":"《史记·晋世家》《赵世家》"}]},
  "v5-qin-books": {"paragraphs":["前213年秦廷宴会上有人援引古代分封批评当时制度，李斯把争论理解为私人以旧说攻击新政，建议限制私藏和以古议今。《史记》记录的命令区分官方收藏、非秦史书、民间所藏《诗》《书》诸子书和医药、卜筮、种树类书，政策目标集中在控制政治知识的传播与议论。","《史记》又把次年咸阳处置诸生与求仙者逃亡、皇帝追究议论等情节相联系。后世常把两事并称，具体受刑者的身份和人数仍须依文献分开理解。秦末兵乱也使官私典籍遭遇损失，书籍散佚有多重原因，不能从焚书令推断所有先秦作品在同一年消失。"],"references":[{"label":"林剑鸣《秦汉史》第三章"},{"label":"《史记·秦始皇本纪》"}]},
  "v5-han-saltmonopoly": {"paragraphs":["汉武帝时期，远征和边防使朝廷需要更加稳定的收入与军需。盐、铁需求广，政府通过专营组织盐业收入和铁器的生产销售，把部分原先由私人经营获取的收益纳入财政。地方的均输机构承担征调和转运，平准机构集中物资，遇价格高低变动再安排买卖。","这些措施让财政能够调动跨郡国的货物，也把官府更深地带入日常市场。交通距离、生产成本和地方执行方式都影响实际效果。《盐铁论》保存了后来对专营的辩论，一方关心边防开支和抑制兼并，一方批评官售铁器的质量与官府逐利。争论揭示了统筹军费与农户使用之间的冲突。"],"references":[{"label":"林剑鸣《秦汉史》第七章第五节“财政、经济政策”"},{"label":"《史记·平准书》"},{"label":"《汉书·食货志》"}]},
  "v5-xin-uprising": {"paragraphs":["新末灾荒、流亡与征敛叠加，荆州一带聚集的绿林力量和青徐之间的赤眉各自发展。绿林各部在北进中与刘氏宗室等合流，拥立刘玄，借恢复汉号扩大号召力。昆阳战败重创新朝主力，随后更始军进取关中，王莽在长安陷落时被杀。","新朝覆亡没有立即形成统一秩序。更始政权需要消化地方将领和宗室之间的权力竞争，赤眉西进入关后又立刘盆子。关中物资短缺、诸军争夺和各地割据继续影响战局。刘秀在河北建立根据地并逐步消灭对手，东汉的建立发生在这场多方战争的后半段。"],"references":[{"label":"林剑鸣《秦汉史》第十三章"},{"label":"《汉书·王莽传下》"},{"label":"《后汉书·刘玄刘盆子列传》"}]},
  "cn-easthan-land-survey": {"paragraphs":["东汉初年经历长期兵乱，地方户口流散，田地登记与实际占有不易吻合。建武十五年，朝廷命郡国检核垦田亩数、户口及年纪，以便掌握赋税和劳役的基础。诏令还要求追查不实登记，因为地方官面对豪强荫蔽的田地和人口时，可能把核查压力转给缺少保护的人。","度田引发官吏舞弊与部分地区的反抗，朝廷追究虚报，并以安抚和军事措施处理动荡。《后汉书》记载的重点是地方隐匿和中央如何纠举。度田使登记问题成为重建秩序的一部分，实际完成程度因地区而异，不能把一纸命令等同于重新平均分田。"],"references":[{"label":"林剑鸣《秦汉史》第十四章"},{"label":"《后汉书·光武帝纪下》《刘隆传》"}]},
  "cn-wei-tuntian": {"paragraphs":["汉末战事破坏粮食生产，大量流民失去稳定居处。曹操迎汉献帝至许后，在许下招集人力开田，并设官管理屯田。由官府组织土地、耕牛等生产条件并分取收成，使后方既有办法重新开垦，也能向军队和官府提供相对稳定的粮食。","屯田向控制区内推广，与后来军队直接参与耕作的做法有联系，具体组织办法与分成因时地而异。其作用首先是稳定曹操集团的军需并掌握生产人口。屯田户也受到管理和租额的约束，不能只从收粮和军功看这项制度，还须看到耕作者承担的负担。"],"references":[{"label":"王仲荦《魏晋南北朝史》第一章"},{"label":"《三国志·魏书·武帝纪》《任峻传》"}]},
  "cn-yongjia": {"paragraphs":["八王之乱削弱了西晋在中原的军队和行政。皇族与将领各拥兵权，洛阳在粮运困难和防守失调中逐渐孤立。永嘉五年即311年，汉国军队攻入洛阳，晋怀帝被俘，王公官民遭杀掠。都城的失守摧毁了西晋原有的政治中心。","洛阳陷落后，晋室仍在关中拥立愍帝，直到316年长安失守，西晋政权才结束。战乱促成多向移民，既有人进入江南，也有人迁入河西、辽东或依附地方坞堡。东晋后来依靠江南的军政网络立足，北方则继续形成并争的政权格局，分裂不是由一次攻城单独造成的。"],"references":[{"label":"王仲荦《魏晋南北朝史》第三、四章"},{"label":"《晋书·怀帝纪》《刘聪载记》"}]},
  "cn-gengxu-soil-registration": {"paragraphs":["北方人口南迁后，东晋在江南设置侨州、侨郡和侨县，沿用移民原籍的地名与组织。原籍户籍同实际居住地分离，在安置移民时有现实作用，时间久了却使赋役归属和地方管辖复杂化。土断就是按照居住土地整理户籍和侨置行政单位的办法。","兴宁二年即364年，桓温主导的一次整顿以干支日名为“庚戌土断”。它使部分移民改按实际居地承担赋役，也便利朝廷清理侨置辖区。土断在东晋、南朝反复实行，涉及已在江南扎根的不同群体，具体适用与豁免不尽相同，不能理解为一次性消除了全部侨籍。"],"references":[{"label":"王仲荦《魏晋南北朝史》第五章"},{"label":"《晋书·哀帝纪》《食货志》"}]},
  "cn-six-garrisons-and-split": {"paragraphs":["北魏在北方设镇以防御柔然，镇兵和居民承担守边任务。政治中心迁到洛阳后，边镇同朝廷之间的地位、待遇和供给差距加深，饥荒及地方治理冲突使危机集中爆发。六镇之一的沃野镇首先发生大规模反抗，朝廷虽能调兵镇压，却难以迅速安置被迁往内地的镇民。","起事与后续动荡使军人集团重新组织。尔朱荣一度以军力控制朝廷，随后高欢与宇文泰分别支配东西两方。534至535年间形成东魏、西魏两廷，北魏的政治统一告终。六镇之乱和北魏分裂之间经过多年权力竞争，不能把两件事当作同一年发生的因果链。"],"references":[{"label":"王仲荦《魏晋南北朝史》第七章"},{"label":"《魏书·肃宗纪》《孝庄纪》"}]},
  "cn-sui-daxing": {"paragraphs":["隋文帝受禅后仍以关中为政治中心。汉长安故城沿用已久，城市空间和水源条件制约新的都城安排。开皇二年，朝廷在龙首原一带营建大兴城，由高颎等主持，宇文恺参与规划。次年迁入新都，宫城、皇城和居民坊市在总体布局中各有位置。","有计划地划分政务区、市场和居民区，使宫廷、官署与大批都城人口能在同一城市中组织起来。唐代沿用并继续经营这座城市，形成后来的长安。隋代初建时的范围和制度与唐朝逐步扩建、使用的状况有差别，不能把盛唐长安的景象全部提前到开皇年间。"],"references":[{"label":"王仲荦《隋唐五代史》第一章"},{"label":"《隋书·高祖纪》《宇文恺传》"}]},
  "cn-two-taxes": {"paragraphs":["唐中期战乱和人口流动冲击了以丁身和旧籍为基础的租庸调征收。地方已出现各种临时征敛，中央需要把它们纳入可以计算和分配的预算。780年，唐德宗采纳杨炎的主张，以居地编户，根据资产等因素定户税，另按田亩征收地税，并安排在夏、秋两季征纳。","改革把财产与田地更加明确地纳入财政依据，也试图约束临时加征。具体征收仍受地区、货币和实物供给影响。以钱计额而折收绢帛等货物时，价格变化可能改变纳税人负担。两税法改变了征税的依据和节奏，此后的实际征敛仍须结合各地执行和新增税目理解。"],"references":[{"label":"王仲荦《隋唐五代史》第三章第二节"},{"label":"《旧唐书·杨炎传》《食货志》"}]},
  "cn-yanyun-cession": {"paragraphs":["936年，河东节度使石敬瑭与后唐朝廷决裂，在晋阳受围时向契丹求援。契丹军出兵击败后唐军，石敬瑭在其支持下建立后晋。承诺交出的幽州、云州及附近州县连接华北平原与北方山地通道，相关交割使契丹把控制伸入这些战略区域。","后晋继承人试图调整对契丹的臣属关系，双方再起战争，最终后晋灭亡。燕云州县的归属随后持续影响周世宗北伐和宋辽战争，但宋辽边界也随战争与谈判变化。理解割让的影响，要分别看州县的行政控制、关隘的通行和后续军事行动。"],"references":[{"label":"王仲荦《隋唐五代史》第八章"},{"label":"李锡厚、白滨《辽金西夏史》燕云交割与侵宋战争"},{"label":"《旧五代史·晋书·高祖纪》"}]},
  "cn-movable-type": {"paragraphs":["沈括记载，北宋庆历年间毕昇把字刻在胶泥上，烧硬成为可反复使用的字模。排版时在铁板上铺可加热软化的黏合材料，把字模紧密排入铁范，再加热并压平。印完以后重新加热，便能取下字模供下一版使用。常用字需备多个字模，罕见字可以临时制作。","这个办法把逐版刻书改为用独立字模拼成版面。它减少了重新刻整版的需要，却增加了制字、检字、保管和校正的工序。沈括对小批量与多份印刷成本的比较，说明技术的优势取决于印量和作业条件。北宋以后雕版继续广泛使用，两种办法各有适用场景。"],"references":[{"label":"陈振《宋史》第十七章"},{"label":"沈括《梦溪笔谈》卷十八“技艺”"}]},
  "cn-yuan-grain-routes": {"paragraphs":["元廷以大都为中心，南方尤其江南是重要的税粮来源。长距离陆运代价大，旧有河道也不能直接满足新都的需要。元朝一面疏通和改造会通河、通惠河等水道，一面组织粮船从江南出海，沿海航行后在直沽等地转运，形成并用的运输路线。","海运能把大宗粮食送到北方，但依赖船只、熟悉航路的人手和相对有利的风汛，海损无法完全避免。河运则需要维持水位、闸坝和转输环节。两类运输办法共同支持大都的消费和军政供给，也使航路、仓场和沿线城市成为理解元代财政的重要线索。"],"references":[{"label":"周良霄《元史》第九章"},{"label":"《元史·食货志·海运》"}]},
  "cn-southern-ming": {"paragraphs":["1644年北京明廷覆亡后，仍在南方的明宗室、官军和地方力量陆续拥立新的朝廷。南京弘光政权率先成立，清军南下后迅速瓦解。此后隆武、永历等政权先后延续，鲁王监国也在东南活动。各方既要与清军交战，也要解决宗室继承、军权和供给问题。","战事的重心从江淮、东南沿海移向西南，永历政权后期借助原大西军将领等力量维持。永历帝被俘并于1662年遇害后，郑氏在台湾的政治军事活动仍持续多年。南明各政权有时间重叠，不能把它们排成一个中央能连续调度全国的单线王朝。"],"references":[{"label":"南炳文、汤纲《明史》第二十二章“南明政权及农民军余部的拥明抗清”"},{"label":"《明史·诸王世表》"}]},
  "cn-sino-french-war": {"paragraphs":["法国在越南推进殖民扩张，清朝向北部驻军，双方在越南的政治和军事冲突日益加剧。交涉没有阻止战争扩大，法军又攻击福建马尾，海上压力延伸至台湾和澎湖。战场由越南北部、广西边境到东南海防，陆军与水师面临不同的指挥和补给难题。","1885年冯子材等在镇南关方向取得胜利，法国国内政局也因前线消息震荡。随后两国仍以谈判结束战争，清政府签约承认法国同越南订立的条约，并安排边界与通商事宜。局部战场的胜负和外交结果必须分别考察，战事同时暴露沿海防御与军队协同的困难。"],"references":[{"label":"南炳文主编《清史》“中法战争”节"},{"label":"《中法会订越南条约》"}]},
  "cn-late-qing-reform": {"paragraphs":["庚子事变后，清廷以新政重组军事、学校、财政和官署。科举废止，新式学堂和留学为人员培养开辟新渠道，练兵与警政扩展也需要大量财力。新机构与原有督抚体系并行，中央试图统一制度，地方则在筹饷、用人和推行进度上发挥实质作用。","预备立宪把改革进一步带到国家权力分配上。1908年的《钦定宪法大纲》仍把多项权力保留给君主，地方咨议局和中央资政院随后提供了议事场合。立宪团体要求缩短筹备期限，1911年新内阁的组成又引起争议。新政留下学校、军队和行政变革，其政治过程也扩大了围绕参与权与财政负担的争论。"],"references":[{"label":"南炳文主编《清史》清末新政与预备立宪相关章节"},{"label":"《钦定宪法大纲》"}]},
  "v5-shang-oracle": {"paragraphs":["殷墟出土的大量甲骨来自晚商王室占卜。卜人把龟甲、兽骨加工并钻凿，灼烧后观察裂纹，有些又把日期、询问事项或判断刻在甲骨上。不同残片记载的内容可以涉及祭祀对象、天气、田猎、征伐、疾病与生育，并非每片都保留完整程序。","甲骨有明确的文字形态，但记录受王室关注事项和考古保存条件影响。把能够拼合或归入同组的刻辞整理出来，才能讨论当时的称谓、王室世系和行政活动。它们可以核对部分传世商史，也带来新的问题。读到一条关于出征的占问，还要区分这只是询问、已经作出决定，还是附有实际结果。"],"references":[{"label":"胡厚宣、胡振宇《殷商史》学术文化篇"},{"label":"《甲骨文合集》"}]},
  "v5-zhou-gonghe": {"paragraphs":["厉王时期，周王室试图加强对资源和政治言论的控制。传世叙事将厉王奔彘与国人反抗相联，周都失去正常的王权中枢。此后直至宣王即位的过渡岁月被称为共和。传世纪年通常从前841年起算，使此后周王纪年有了较稳定的衔接起点。","谁在过渡期实际主持政务，资料说法不同。《史记》以周公、召公共理政务解释“共和”，一些古本材料及《系年》所载又涉及共伯和。两种叙事都把王出奔与政务延续联系起来。这里的“共和”是古史纪年和政治叙述中的称呼，与近代共和制度没有直接对应关系。"],"references":[{"label":"杨宽《西周史》第四编"},{"label":"《史记·周本纪》"},{"label":"清华简《系年》"}]},
  "v5-eastern-chengpu": {"paragraphs":["前632年以前，楚势力深入中原诸侯之间，宋受到楚及其盟国压力。晋文公为救宋和扩大晋的影响，先向与楚关系密切的曹、卫用兵，并通过政治安排争取诸侯配合。晋军与楚军的接战不是两国偶遇，而是围绕宋的安全和诸侯选择展开的竞争。","城濮交战时，晋军击破楚军侧翼，楚军主力未能挽回局势，楚将子玉退兵。晋随后通过会盟巩固诸侯关系并得到周王室的承认。晋取得盟主地位后，楚仍是可以持续介入中原的强国，因此这场胜利改变的是联盟与力量的阶段性配置。"],"references":[{"label":"顾德融、朱顺龙《春秋史》第二章"},{"label":"《左传·僖公二十七年、二十八年》"}]},
  "v5-eastern-bashu": {"paragraphs":["前316年，蜀、巴及邻近势力发生冲突，秦廷内部也在考虑将兵力投向中原还是西南。《史记》记载司马错主张取蜀，着眼于获取土地、人口和财货，同时避免立即在中原同多国对抗。秦军穿过秦岭通道进取，先后控制蜀、巴。","征服之后，秦需要处理地方贵族、官吏派遣和交通供给，控制逐步巩固。成都平原及长江上游由此进入秦的军政资源网络，秦日后也能从西南方向对楚施压。后续地方经营和水利开发发生在不同阶段，不能把长远变化全算作出兵当年立刻取得的成果。"],"references":[{"label":"杨宽《战国史》第八章"},{"label":"《史记·张仪列传》《秦本纪》"},{"label":"常璩《华阳国志·蜀志》"}]},
  "qinend": {"paragraphs":["巨鹿失利与各地兵变使秦廷失去调兵平叛的主动。赵高迫使秦二世自尽后立子婴为秦王，子婴随即诛杀赵高，但宫廷内部的更替已无法恢复关东统治。与此同时，刘邦部沿另一条路线攻入关中，推进到咸阳附近。","子婴向刘邦交出政权，秦的中央统治结束。刘邦入关后的约法和军队驻扎，仍受各路反秦力量争夺关中的形势制约。项羽随后率军到达并重新分封诸侯，秦亡之后经历的是权力重组和楚汉战争，汉政权并未在子婴投降时立即建立。"],"references":[{"label":"林剑鸣《秦汉史》第四章"},{"label":"《史记·秦始皇本纪》《高祖本纪》"}]},
  "v5-han-latecrisis": {"paragraphs":["西汉中后期，土地集中与流民问题多次出现在奏议中。朝廷仍依赖郡县掌握登记人口和田地，而大族可以通过土地与依附关系取得劳动力及收入。灾荒与物价、救济能力和地方执行相互作用，使部分农户更难回到稳定编户生活。限田等主张受到权贵利益和执行条件制约。","与此同时，皇帝身边的外戚家族有机会通过宫廷侍从、辅政和官职安排积累影响。王氏地位上升为王莽掌权创造了条件，但其摄政和改朝还需要诏令、符命及官僚合作。社会困境与宫廷权力变化是两条互有影响的线索，不能只用一项灾害或某一家族解释西汉终结。"],"references":[{"label":"林剑鸣《秦汉史》第十一章"},{"label":"《汉书·食货志》《元后传》"}]},
  "cn-anshigao": {"paragraphs":["东汉后期的洛阳汇聚来自西域的商人、旅人和宗教传播者。僧传把安世高记作来自安息的僧人，并将他的译经活动系在汉桓帝以后。此时译者需要在不同语言与修行术语之间建立对应，也需要依靠能够记写、传抄和讲解的合作者。","现存目录把一批禅观、数息和教义条目系于安世高，其中具体归属有文献辨析问题。早期译经的重要性在于为汉语读者提供可以讲习和实践的佛教文本，并逐步形成术语。其经历常带有僧传的宗教叙事色彩，译作归属宜结合经录、传本及用语比较来考察。"],"references":[{"label":"林剑鸣《秦汉史》第二十章"},{"label":"僧祐《出三藏记集》卷十三"},{"label":"《高僧传·译经》"}]},
  "cn-gaopingling": {"paragraphs":["魏明帝死后，曹爽与司马懿同受辅政之命。曹爽集团掌握皇帝近侍及政务，司马懿一度退居。249年魏帝曹芳出城祭扫高平陵，曹爽兄弟随行，司马懿趁此在洛阳调兵并控制关键机构，向在外的曹爽施加压力。","曹爽放弃抵抗后，其集团被清除，司马氏取得控制朝廷的优势。政变后魏帝仍在位，司马氏历经后续废立和战争，直到司马炎代魏才改变国号。高平陵是权力转移的重要节点，后来晋朝本纪如何解释政变正当性，也须放回其编修立场理解。"],"references":[{"label":"王仲荦《魏晋南北朝史》第一章"},{"label":"《三国志·魏书·三少帝纪》"},{"label":"《晋书·宣帝纪》"}]},
  "cn-easternjin-start": {"paragraphs":["西晋末年，司马睿原以宗室身份驻守建邺。洛阳和长安接连陷落后，原来的中央命令难以维持，江南的军队、地方士族及渡江的官员成为重建政权的实际依托。王导等人在不同集团之间协调，帮助司马睿取得地方支持。","司马睿先称晋王，318年即皇帝位，以建康为都。朝廷延续晋的名号，但财政、军队和人事都要依赖江南及长江上游的新格局。后来王敦等掌兵者与建康发生冲突，反映出东晋建立之初必须在中央名义与地方军事力量之间维持平衡。"],"references":[{"label":"王仲荦《魏晋南北朝史》第五章"},{"label":"《晋书·元帝纪》《王导传》"}]},
  "cn-zuchong-calendar": {"paragraphs":["南朝历法需要兼顾朔望、节气与置闰。祖冲之据前代历算并参校观测，编成《大明历》，把岁差纳入推算，并提出新的置闰周期。他的议论涉及观测所得与既有历数逐渐偏离时，如何调整计算依据。","刘宋朝廷讨论历法时，戴法兴等提出异议，祖冲之逐项回应。新历没有在他提出时立即行用，到梁代才获施行。历书的编成、争辩和颁行各有时间，说明更好的测算方案还须经过朝廷审议及制度转换，才能成为官府据以安排日期的历法。"],"references":[{"label":"王仲荦《魏晋南北朝史》第十二章"},{"label":"《宋书·律历志下》"}]},
  "cn-yuanhe": {"paragraphs":["安史之乱后，若干方镇掌握区域军队、税赋和任官权，中央仍需同它们议定承袭和供赋。唐宪宗即位后择机处理拒命方镇，其中淮西吴元济据地不受朝命，朝廷几经争论仍继续用兵。裴度主持战事期间，李愬率军乘雪夜突入蔡州，擒获吴元济。","淮西平定使一部分藩镇暂时接受中央调度，元和年间朝廷权威有所恢复。中央仍依赖各道兵力作战和供应。兵权结构、朝廷内部争斗以及地方财赋问题并未随蔡州攻克而解决，后续继承争端仍能引发中央与方镇的再度对抗。"],"references":[{"label":"王仲荦《隋唐五代史》第二章"},{"label":"《旧唐书·宪宗纪》《裴度传》"},{"label":"《资治通鉴》唐宪宗元和年间"}]},
  "cn-qing-maritime-trade": {"paragraphs":["清初为压制东南沿海抗清力量，实施海禁及迁界。台湾纳入清朝统治后，康熙朝调整政策，开放海上贸易，在粤、闽、浙、江设海关。海关征税、验货并管理船只，使官府在承认跨海贸易的同时把航行纳入登记和稽查。","乾隆朝对西洋商船来华贸易实行更集中的广州管理，商人需通过特定行商办理交易。口岸制度涉及征税、商人债务、外商居留和地方监管。广州成为西洋商船对华贸易的主要渠道，并不意味着沿海民间运输或对亚洲各地的贸易都只剩广州一个口岸。"],"references":[{"label":"南炳文主编《清史》“从海禁到闭关政策的实施”"},{"label":"《清圣祖实录》《清高宗实录》"},{"label":"梁廷枏《粤海关志》"}]},
  "cn-zhangheng-science": {"paragraphs":["张衡在东汉两度担任太史令，职务涉及观象、历法与相关仪器。他以《灵宪》讨论天地和天体结构，又参与制作浑天仪器，尝试将天体运行的模型转成可演示、可检验的装置。传世记载关于仪器的称呼并不都指同一种用途，应把天体模型和实际测量器具分开。","《后汉书》也描述候风地动仪以龙、蟾蜍和铜丸提示震动方向，并记有远方地震消息印证仪器反应的故事。原器未能留存，文字不足以唯一确定内部结构。现代复原是依据文献和力学提出的方案，不能直接当作张衡装置的原样。"],"references":[{"label":"林剑鸣《秦汉史》第二十章"},{"label":"《后汉书·张衡列传》"}]},
  "cn-zhuge-northern-campaigns": {"paragraphs":["刘备去世后，诸葛亮主持蜀汉政务，重新联络孙吴，整顿南中，再将军事力量移向汉中。自228年起，蜀军多次由汉中向陇右、关中方向进军。第一次出师中街亭失守，蜀军退回，随后各次攻守的路线、目标和成果并不相同。","蜀汉可以依靠汉中作为北进基地，却要在山地道路上持续运送军粮，魏军则能凭据关中防线等待或反击。234年诸葛亮出斜谷与司马懿相持于五丈原，病逝后蜀军撤退。北伐延续了蜀汉争取主动的战略，也暴露其动员与运输约束。《三国演义》的战事描写需同史传记录分别阅读。"],"references":[{"label":"王仲荦《魏晋南北朝史》第一章"},{"label":"《三国志·蜀书·诸葛亮传》"}]},
  "cn-jin-land-system": {"paragraphs":["西晋统一后，朝廷需要将不同地区的赋役归入较统一的安排。《晋书·食货志》记载占田、课田和户调，涉及按身份、丁口等条件规定田额和应纳绢绵。官品与荫客也有相应规定，意味着土地和依附人口的登记同等级身份相连。","这些规定提供了理解晋廷财政目标的依据。占田额、应承担课税的田额与实际占有土地之间并不能简单画等号，史料也不足以证明朝廷曾依规定向所有人普遍分田。要判断制度效果，仍须区分中央规范、地方执行和战乱中人口流动带来的变化。"],"references":[{"label":"王仲荦《魏晋南北朝史》第三章"},{"label":"《晋书·食货志》"}]},
  "cn-fujian-unification": {"paragraphs":["苻坚在前秦取得政权后，任用王猛处理官吏治理、地方秩序及军事事务。前秦先同北方其他政权保持竞争，继而在370年灭前燕，又向西南和西北扩展，最终控制前凉、代等政权的旧地。北方的统一是在多轮征服与接收中形成的。","新并入的地域有自己的军队、旧王族和地方势力，前秦需要通过迁徙、授官和驻军将其纳入中央。统一扩大了征调能力，也留下维持联盟和忠诚的难题。淝水之战失败后，许多原有政治集团重新起兵，显示这种整合尚未转化成长期稳定的统治。"],"references":[{"label":"王仲荦《魏晋南北朝史》第四章"},{"label":"《晋书·苻坚载记》《王猛载记》"}]},
  "cn-sui-koguryo": {"paragraphs":["隋炀帝在612至614年多次出兵高句丽。第一次用兵规模很大，军队从辽东和海路展开行动，但分兵指挥、坚城攻守及长距离运粮给推进带来困难。深入高句丽腹地的部队遭遇反击并损失严重。第二次用兵又因杨玄感在后方起兵而中断。","第三次出兵以双方交涉收场，隋并未建立对高句丽的统治。多次征发使内地承担军粮、劳役和运输的压力，也让军队长期远离许多已经发生动荡的地区。战争是隋末危机扩大的因素之一，要与工程徭役、地方起事及朝廷失控的时间线合看。"],"references":[{"label":"王仲荦《隋唐五代史》第一章"},{"label":"《隋书·炀帝纪》《高丽传》"}]},
  "cn-huichang-buddhism": {"paragraphs":["唐武宗时期，朝廷对佛寺和僧尼的限制逐渐加严。会昌年间，以裁撤寺院、令僧尼还俗及处置寺产等措施推进整顿。寺院既是宗教空间，也掌握财物并聚集人口，因此官府处置寺院会牵涉户籍、赋税、铜器回收和地方社会。朝廷推崇道教与清理寺产等因素同时发挥作用。","日本入唐僧圆仁的行记保留了地方执行及僧人应对的观察，可与朝廷诏令互证。武宗死后，宣宗朝调整政策，部分寺院与僧团恢复活动。会昌措施对寺院物质基础和佛教传播造成冲击，但不同地区和宗派的延续情形有所差异。"],"references":[{"label":"王仲荦《隋唐五代史》第九章"},{"label":"《旧唐书·武宗纪》"},{"label":"圆仁《入唐求法巡礼行记》"}]},
  "cn-later-tang": {"paragraphs":["李存勖继承河东集团后，以晋王身份同后梁争夺河北与中原。923年他称帝建立后唐，随后乘战机进攻后梁都城，后梁迅速灭亡。新政权取得中原重要地区后，又须处理旧梁官员、藩镇和河东旧将之间的关系，并承担进一步用兵所需的军费。","后唐军灭前蜀扩大了版图，政权内部的饷给、人事和军队信任却未能随领土扩张得到解决。926年兵变接连发生，李存勖在洛阳变乱中死去，李嗣源继位。这里的“后唐兴亡”包含庄宗统治的骤变与王朝后来延续两条线，后唐并未在庄宗去世当年终结。"],"references":[{"label":"王仲荦《隋唐五代史》第八章"},{"label":"《旧五代史·唐书·庄宗纪》"}]},
  "cn-western-liao": {"paragraphs":["辽朝在金军攻势下失去主要政治中心时，宗室耶律大石率部向西北转移，沿途吸收原辽人员并联合当地力量。其政权后来进入中亚，以虎思斡耳朵为中心，控制或影响不同城邦、绿洲与游牧集团。对当地统治者，西辽可保留其部分治理权，通过贡赋和政治约束维系关系。","西辽在卡特万之战取胜后，在中亚的势力更加稳固。其政治传统同辽有联系，所治理的土地、人口与宗教环境却已不同。汉文史籍关于迁徙和纪年记载有限，中亚和伊斯兰文献的名称及时间需要互相核对，因此建国和称帝的标年可见不同口径。"],"references":[{"label":"李锡厚、白滨《辽金西夏史》西辽相关章节"},{"label":"《辽史·天祚皇帝纪》"}]},
  "cn-yuan-retreat": {"paragraphs":["元末各支武装扩张时，朱元璋先经营江南，再向北推进。徐达等所统明军夺取山东、河南等地后继续北上，元廷难以重新组织大都外围的防线。1368年元顺帝率朝廷人员离开大都北走，明军随后进城，改大都为北平。","失去大都使元廷不能继续以原有政治中心统治中原。元朝宗室、军队和政治名号仍在北方延续，明军仍要对北方出兵，双方也持续争夺边地。以大都失守作为元代通史的终点，是以中原政治格局为口径，不能据此认定北方元廷在1368年即时消失。"],"references":[{"label":"周良霄《元史》第十二章"},{"label":"《元史·顺帝纪》"},{"label":"《明太祖实录》"}]},
  "cn-ming-liaodong-war": {"paragraphs":["明后期，努尔哈赤整合女真各部并建立后金，随后夺取抚顺等据点。明廷于1619年组织多路进军，后金在萨尔浒一带集中力量迎击分开的明军。战后明朝难以维持原先的攻势，辽阳、沈阳等要地在随后几年失守，朝廷逐步将防线转向辽西。","辽西据点仍有守御能力。宁远、锦州等处的筑城、火器与粮饷维持了防线，后金也在调整进攻路线和军队组织。辽东形势的变化牵涉战场指挥、后方财政、兵员与边地居民迁徙。萨尔浒是一处重要转折，却不能用一战直接解释此后二十余年的战事和明廷覆亡。"],"references":[{"label":"南炳文、汤纲《明史》第十八、十九章"},{"label":"《明史·杨镐传》《袁崇焕传》"}]},
  "qi": {"paragraphs":["启在传世王表中被列作禹的继承者。《孟子》把权力交接解释为诸侯、讼狱和讴歌者转而归附启，由此论证王位取得并非完全由前一任君主私下授予。《史记》则把有扈氏的不服与甘之战接在启即位之后，留下了新统治如何应付反抗的另一条叙事线。","两种说法都把继承问题放在夏王权形成的中心，却各自服务于政治议论或本纪编排。启的生卒和在位年数缺少可独立验证的材料。阅读时可把它与后世禅让、世袭之辩相连，避免从一则故事推导出所有早期社群同时改变继承制度的结论。"],"references":[{"label":"王玉哲《中华远古史》第四章第二节"},{"label":"《孟子·万章上》"},{"label":"《史记·夏本纪》"}]},
  "v5-wuding": {"paragraphs":["武丁是晚商王室中最有条件结合同时代材料研究的商王之一。卜辞里的王反复询问祭祀、田猎、收成和战事，有些刻辞还记录事后应验与否。借助称谓、贞人分组和出土层位，可以把一部分记录归入武丁时期，看到他如何安排王室日常政务。","妇好等人出现在同时期占卜记录中，说明王并非独自完成征发、祭祀和作战。传世文献又保存了武丁访求傅说等故事，重在解释中兴之君怎样用人。卜辞和后世叙事的关切不同，不应据后出的故事去填补所有甲骨残片中的空白。"],"references":[{"label":"胡厚宣、胡振宇《殷商史》国事概要篇"},{"label":"《史记·殷本纪》"},{"label":"殷墟武丁期甲骨卜辞"}]},
  "v5-chengwang": {"paragraphs":["成王承继武王时，周刚取代商，东方旧有势力与新封诸侯的秩序尚待稳定。周公参与摄理政事，东方叛乱、平叛后的重新封建以及洛邑的营建，都发生在成王时代。朝廷由此把征服所得的土地和人口纳入可以驻守、调度与举行礼仪的格局。","《史记》把周公还政写成由摄政到亲政的转折，传世诰文与西周铜器铭文则保存不同侧面的王命和赏赐。它们使人看到王权要借助宗族、重臣和诸侯运行。成王生卒与在位纪年的精确换算仍有讨论，阅读时可以先抓住东征、建都与亲政的先后关系。"],"references":[{"label":"杨宽《西周史》第一编"},{"label":"《尚书·洛诰》"},{"label":"《史记·周本纪》"}]},
  "v5-jinwengong": {"paragraphs":["晋文公即重耳，因晋国内部的继承斗争长期在外。他先后依附多个诸侯，最后得到秦穆公支持回晋即位。流亡经历使他同各国君主、随从和贵族建立了复杂关系。归国后要巩固统治，他既需要安置旧从，也要维持能支撑对外用兵的国内联盟。","周王室发生危机时，晋出兵护送周襄王复位。其后晋军在城濮击败楚军一方，并通过会盟取得政治声望。传统故事常强调晋文公的个人机变，霸权的实际基础还在晋国兵力、诸侯合作以及能够借用周王室名义协调行动。"],"references":[{"label":"顾德融、朱顺龙《春秋史》第二章"},{"label":"《左传·僖公二十三年、二十四年、二十八年》"},{"label":"《史记·晋世家》"}]},
  "v5-mengtian": {"paragraphs":["蒙恬出身秦国将门，参与统一战争，后来受命统兵北上。秦在河套一带击退匈奴势力后设置县、迁入人口，并经营边塞。蒙恬所主持的北方事务既需要军队夺取要地，也需要从内地调运粮食与人力，借助城塞和道路维持驻军。","秦始皇在巡行中去世，赵高、李斯等拥立胡亥，扶苏与蒙恬被卷入继承危机。蒙恬被囚后死去，北部军政也随宫廷权力重组发生变化。《史记》的蒙氏传把他个人的功业与秦朝兴亡相连。今人不能据传说将现存历代长城都归于蒙恬一人。"],"references":[{"label":"林剑鸣《秦汉史》第三章"},{"label":"《史记·蒙恬列传》《秦始皇本纪》"}]},
  "v5-sanghongyang": {"paragraphs":["桑弘羊从宫廷财政事务起家，在汉武帝对外用兵和边防开支增加时，参与组织盐铁专营、均输与平准。他的办法着眼于把各地物产、市场价格和国家财政联系起来，使官府能通过调运与买卖取得收入和物资。地方执行的成本与利益分配，也是这一政策能否奏效的条件。","昭帝时期召开的盐铁会议上，桑弘羊一方强调既有制度可以支撑边备、限制富商控制物资，贤良文学则批评官营侵害民间利益。《盐铁论》是桓宽整理的论辩文本，不能当成现场逐字笔录，但能用来追踪中央财政与地方民生为何被放在同一场争论中。"],"references":[{"label":"林剑鸣《秦汉史》第七、九章"},{"label":"《史记·平准书》"},{"label":"《盐铁论》"}]},
  "v5-fanchong": {"paragraphs":["樊崇是赤眉军早期领袖。王莽末年，他在东方聚众，随着饥荒和官军征讨加剧，部众逐渐扩大。《后汉书》写到其部在交战前涂红眉毛，以便与对方相区别，赤眉之名即与这段战争记忆相连。早期队伍依靠推举首领和军中约束维持，组织方式与朝廷官军有别。","赤眉入关后推立刘盆子，以汉宗室身份为政权提供名义。长安周边的供给不足和各部约束困难，使军队无法把军事优势转化为稳定统治。赤眉撤离关中时遭刘秀军阻截，最终归降。樊崇的经历可以放在新朝灭亡后多支武装竞争的过程中理解。"],"references":[{"label":"林剑鸣《秦汉史》第十三章"},{"label":"《后汉书·刘玄刘盆子列传》"}]},
  "banchao": {"paragraphs":["班超早年曾从事文书工作，后随窦固出塞，被派往西域活动。东汉与北匈奴争夺影响力的过程中，鄯善、于阗、疏勒等地各有自己的王室与利益。班超能够行动，靠的是使团、当地盟友和朝廷后续支援，许多时候需要应对各城之间的冲突。","他长期留驻西域，后来出任西域都护，并派甘英西行寻访大秦。甘英止于大海之滨，没有到达罗马世界的核心区域。班超晚年请求归国，回到洛阳不久病逝。他的经历显示东汉的西域经营需要长期驻留和持续协商，远比一次使节往返复杂。"],"references":[{"label":"林剑鸣《秦汉史》第十五章"},{"label":"《后汉书·班超列传》《西域传》"}]},
  "luxun": {"paragraphs":["陆逊出身江东大族，早年在孙权政权中处理地方事务和军事征发。孙吴谋取荆州时，他与吕蒙配合，对关羽表现谦抑，降低对方对东线的戒备。荆州易手后，刘备率军东进，陆逊在夷陵一线统军，等到蜀军长期驻扎、战线拉长后发动反攻。","夷陵之战使孙吴保住长江中游要地，陆逊也由此成为吴国重要的军政人物。晚年任丞相时，他介入孙权诸子的继承争议，并因屡次受到责问而忧愤。前后经历连在一起，可以看到江东士族将领既要守卫边境，也深受宫廷政治制约。"],"references":[{"label":"王仲荦《魏晋南北朝史》第一章"},{"label":"《三国志·吴书·陆逊传》"}]},
  "duyu": {"paragraphs":["杜预在西晋兼有制度建设、军政和经学经历。参与典律和行政事务后，他出镇荆州，对长江中游的防御与进军条件作出判断。晋朝讨论是否攻吴时，他力主抓住机会。灭吴战争中，荆州方向的军队突破江陵一线，与顺江东下及其他方向的军队形成配合。","灭吴之后，杜预继续处理荆州水利、交通和地方治理。他为《春秋》《左传》作集解，将传文与编年次序互相参照，形成长期流传的注本。军略和经学是他两条不同的活动线索，前者关联统一战争，后者影响后世如何读先秦史事。"],"references":[{"label":"王仲荦《魏晋南北朝史》第三章"},{"label":"《晋书·杜预传》"}]},
  "wangdao": {"paragraphs":["西晋晚年，王导追随司马睿镇建邺。他协助新来江南的司马氏争取当地大族支持，也联系陆续南渡的北方士人。东晋建国需要有能力征发地方资源的合作者，王导所在的琅邪王氏在其中成为重要支柱。","王敦依靠上游军队进逼建康时，王导在朝廷中仍承担政务，家族势力和皇室之间的关系因此尤为复杂。他在东晋初年历事数帝，以协调不同政治集团见长。传统“王与马共天下”的说法可以提示士族势力之强，具体官职、军权和皇帝决断仍须按事件分别看。"],"references":[{"label":"王仲荦《魏晋南北朝史》第五章"},{"label":"《晋书·王导传》《元帝纪》"}]},
  "jiasixie": {"paragraphs":["贾思勰是北朝农书《齐民要术》的作者，生卒年月缺少可靠记载，传本题署留下他曾任高阳太守的线索。他在书中同时征引前代著述、采用流传的农谚，并记录具体的操作方法。选种、整地、耕耙和播种被安排在相互联系的步骤中，读者可以看到一项操作如何受季节与土壤条件制约。","全书也写到果木、养畜、酿造和食品储藏，所关心的是农业生产与家庭日常经营怎样衔接。它的经验以北方农业条件为重要背景，不能直接推广到所有地带。作者将零散实践和文字材料分门别类保存，是后世了解北朝生产知识的重要依据。"],"references":[{"label":"王仲荦《魏晋南北朝史》第十二章"},{"label":"贾思勰《齐民要术》序及各篇"}]},
  "yuwenkai": {"paragraphs":["宇文恺由北周入隋，先后参与宫室、都城和大型礼仪建筑的经营。隋初营建大兴城时，他承担实际规划事务，需要把宫廷空间、中央官署、居民坊区和道路放在同一城市格局中。朝廷在汉长安故城东南另择城址，为整体规划提供了空间。","隋炀帝时期，宇文恺又参与东都洛阳营建，并为建筑议题制作图样、模型。《隋书》本传对他讨论明堂制度的记载说明，建筑设计既要回应工程条件，也受礼制争论影响。大兴、洛阳都是朝廷组织的大规模工程，其成果还依赖负责选址、役作和供给的众多官员与工匠。"],"references":[{"label":"王仲荦《隋唐五代史》第一章"},{"label":"《隋书·宇文恺传》"}]},
  "jianzhen": {"paragraphs":["鉴真在扬州长期讲授戒律，受到日本僧人荣叡、普照邀请。赴日需要船舶、航路和许可，前几次尝试屡因风浪、行程受阻等原因未成。一次远行漂至海南。鉴真在多次周折中失明，后来经日本使团的船队东渡，于753年抵日。","在奈良，他主持授戒，将戒律知识落实为当地可持续的授戒仪式和制度，后来与唐招提寺的建立相联系。随行者及所携典籍共同构成这次交流。日本僧传是叙述东渡经过的重要文献，阅读时须把航行的困难、人物的宗教声望和后来的纪念传统分别看待。"],"references":[{"label":"王仲荦《隋唐五代史》第六章"},{"label":"真人元开《唐大和上东征传》"}]},
  "qianhongchu": {"paragraphs":["钱弘俶继位后继续经营吴越，政权以杭州为中心，控制两浙及邻近地区。当地水利、海运和城市贸易维系着供给，王室也通过造塔、印经和寺院捐施参与佛教事务。留存的经卷与小塔能够和王室的题记互相印证，使这些活动有了可考的物证。","吴越长期向中原朝廷奉表，并在宋进攻南唐时配合用兵。宋统一进程加快后，钱弘俶于978年入朝交出所辖州县，吴越政权结束。这个选择涉及双方力量的变化及钱氏家族的处境。它为宋接收两浙提供了渠道，却仍需地方官员完成后续的制度和赋役衔接。"],"references":[{"label":"王仲荦《隋唐五代史》第八章"},{"label":"陈振《宋史》第二章"},{"label":"《宋史·吴越钱氏世家》"}]},
  "shenkuo": {"paragraphs":["沈括在北宋任职期间经历水利、财政、边地交涉和天文观测等事务。他曾在司天监参与改进观测，处理仪器、定时与历算之间的配合。与辽使交涉边界时，他也重视以旧档案和地理材料核对双方主张，实践中的资料判断与后来的笔记写作有直接联系。","退居梦溪园后，沈括将见闻分门记录成《梦溪笔谈》。毕昇活字、指南针和自然现象等条目既保存技术细节，也常记录他对前说的比较或自己的观察。笔记并非每件事都是他本人的发明，具体条目要区分所见、转述、推测与前人的成果。"],"references":[{"label":"陈振《宋史》第九、十七章"},{"label":"沈括《梦溪笔谈》"},{"label":"《宋史·沈括传》"}]},
  "guanhanqing": {"paragraphs":["关汉卿是元代杂剧的重要作者。《录鬼簿》将他列入元曲作者的交游与创作谱系，生卒年代和早年经历却没有完整记录。阅读存世剧本能更具体地看到他的写作方式。角色通过唱词、说白和舞台行动表达判断，冲突在若干折中逐步推进，而非用叙述者一次交代。","《窦娥冤》把被迫认罪、冤情显露和翻案连接起来，借舞台集中表现司法失序。《救风尘》则由赵盼儿的周旋推动情节，呈现人物如何在不利处境中寻找办法。不同传本的文字和署名有待分辨，作品提供的是经舞台加工的社会经验，不宜直接当作案件档案。"],"references":[{"label":"周良霄《元史》第十三章"},{"label":"钟嗣成《录鬼簿》"},{"label":"关汉卿《窦娥冤》《救风尘》"}]},
  "songyingxing": {"paragraphs":["宋应星是晚明江西奉新人，曾中举并担任地方教职。崇祯十年刊行的《天工开物》把农作、纺织、制盐、冶铸、造纸等生产分篇说明。它常从原料、器具、工序和成品讲起，让读者看见从种植或采掘到加工的劳动怎样连续展开。","例如书中把稻作条件、品种差异和加工步骤分别处理，也会比较材料、地区及工艺的不同做法。其知识来自当时的生产经验、观察和汇集，文本与图示能相互说明。书中某些判断仍受时代条件所限，不能把记录的工艺直接视为晚明全国统一的规范。"],"references":[{"label":"南炳文、汤纲《明史》第二十五章“明代的科学技术”"},{"label":"宋应星《天工开物》自序及各卷"}]},
  "zhangzhidong": {"paragraphs":["张之洞先后任两广、湖广总督，参与经营制造、交通和新式教育。他在湖广推动汉阳铁厂等项目，需要协调矿石、燃料、机器、运输和资金。早期筹办遇到原料、设备和管理等困难，企业后来调整经营方式，显示大型工业的难题并不止于购置设备。","甲午战争后，张之洞撰《劝学篇》，主张在既有政治伦理框架中扩展新式知识和实务学习。此后他参与清末教育制度改革。学校、军工和工业各有不同的政策目标，却都需要人才和持续财政供给。把这些事业放在一起，可以理解督抚主持的新政如何同时受地方条件与中央制度制约。"],"references":[{"label":"南炳文主编《清史》洋务与清末新政相关章节"},{"label":"张之洞《劝学篇》"},{"label":"《张文襄公全集》"}]},
  "ann-chron-world-east-asia-0582": {"paragraphs":["丰臣秀吉死后，年幼的丰臣秀赖留在大坂，德川家康与丰臣政权内部其他大名的矛盾迅速加深。1600年，家康东进讨伐上杉景胜，石田三成等趁机组织反对家康的联盟，推毛利辉元为名义领袖。双方决战在美浓的关原，连接畿内与东国的交通要道，使战场胜败直接关系各大名继续动员的能力。","小早川秀秋率军倒向家康，西军的阵线瓦解，石田三成战后被捕处死。家康借战胜后的领地重分配巩固权力，1603年就任征夷大将军。丰臣家此时仍在大坂拥有领地，直至1614—1615年的大坂之阵后才覆亡。关原打开了德川建立幕府的道路，丰臣势力的最终退出则有另一个阶段。"],"references":[{"label":"《德川实纪》卷一「东照宫御实纪」；国立公文书馆所藏《关原军记大成》"}]},
  "ann-chron-world-south-asia-0654": {"paragraphs":["孔雀王朝向印度东部扩展时，羯陵伽仍控制着今奥迪沙附近的沿海地区。大摩崖诏令第十三号将征服记在阿育王加冕后的第八年。诏令称战事造成大批死亡和人口迁移，并特别提到亲属离散与不同社会群体承受的痛苦。其伤亡和迁徙数字由统治者自行公布，缺乏独立的统计记录。","战后的诏令将统治目标表述为以「法」感化臣民及邻国。这一政策主张包括约束杀戮、尊重不同宗教群体，也保留惩治的权力。诏令是了解阿育王如何公开解释征服后施政取向的第一手材料，关于他个人何时、如何接受佛教，还须结合其他诏令与年代较晚的佛教传记。"],"references":[{"label":"阿育王大摩崖诏令第十三号"}]},
  "ann-chron-world-southeast-asia-0802": {"paragraphs":["1287年，元军再次水陆进攻大越。陆军深入后需要从海上获得给养，陈朝军队在云屯一带打击粮船，削弱了入境部队的持续作战能力。元军决定撤退时，乌马儿所部水军沿白藤江出海，陈兴道布置兵力截击。","越方史书将战胜与水下木桩、潮汐以及协同攻击联系起来。水位下降后，撤退的船队失去活动空间，乌马儿被俘。越方和元方记载各有侧重，具体兵力与损失不宜混用。战役帮助陈朝挫败这次征服，双方此后仍通过使臣往来维持政治关系。"],"references":[{"label":"《大越史记全书》陈纪；《元史》卷二〇九《安南传》"}]},
  "ann-chron-world-central-west-asia-0337": {"paragraphs":["前七世纪末，新亚述帝国在王位冲突和多地反抗中受到削弱，巴比伦王那波帕拉萨尔与米底军队逐渐转入攻势。前612年，双方围攻尼尼微。《尼尼微陷落编年史》从巴比伦一方记下围城持续数月，城内宫殿和居民区遭到严重破坏。","尼尼微失陷后，亚述残余势力仍在哈兰维持活动，并一度得到埃及支持。巴比伦与其盟军的后续军事行动继续摧毁原有的亚述统治，近东的权力格局随之重组。尼尼微宫殿遗址及泥板文书保存了亚述的宫廷文化，但城市毁灭的细节需以不同层次的考古证据和有立场的编年记载相互校验。"],"references":[{"label":"大英博物馆馆藏 BM 21901《尼尼微陷落编年史》"}]},
  "ann-chron-world-europe-0223": {"paragraphs":["詹姆斯二世在宗教政策和王权运用上与议会及部分精英发生冲突。1688年，荷兰执政威廉登陆英格兰，詹姆斯离境。次年，议会邀请威廉与玛丽共同继位，并将此前提出的权利宣言写入法律，以约束君主绕过议会所采取的措施。","法案否定王权擅自停止法律和未经议会批准征税的做法，也涉及议会选举自由、议会内言论以及和平时期常备军的条件。它是在王位更迭中形成的制度安排，政治权利仍受财产、性别和宗教限制。理解此法的影响，可以把它与其后的财政控制和政府责任制度的发展分开考察。"],"references":[{"label":"英国议会档案馆《权利法案》（1689年）；英国议会「The Bill of Rights」专题"}]},
  "ann-chron-world-africa-0874": {"paragraphs":["埃及第十八王朝晚期，阿蒙霍特普四世逐步提升太阳圆盘阿顿的宗教地位。他改名为阿肯那顿，并兴建新都阿赫塔顿（今阿玛尔纳），把王室仪式、神庙经济和宫廷生活移到新的地点。壁画与浮雕上，阿顿的光束伸向国王与王后，王室在供奉中的中介地位格外突出。","改革后期一些传统神祇的名字被抹去，不过民间小型护符和家庭遗物显示传统信仰并未消失。阿肯那顿死后，王廷逐步恢复旧有祭祀并离开新都。阿玛尔纳遗址因此留下相对集中的城市生活、艺术和外交文书，改革对宫廷的强烈冲击与它在民间传播的限度可以并列阅读。"],"references":[{"label":"大都会艺术博物馆 Heilbrunn Timeline「The Amarna Period」；阿玛尔纳王陵《阿顿大颂歌》"}]},
  "ann-chron-world-americas-1080": {"paragraphs":["美国内战打到1862年，联邦政府逐步把打击奴隶制纳入战争政策。林肯在安提坦战事之后发布预告，规定若叛乱地区未在指定期限内恢复服从，联邦将宣布那些地区被奴役者获得自由。正式宣言于1863年1月1日生效。","宣言以总统的战时权力发布，其范围指向仍在叛乱的地区，忠于联邦的蓄奴州以及文书明确豁免的地区未被同样覆盖。宣言承认合适的黑人可进入联邦军服役，扩大了反奴隶制与军事动员的联系。1865年通过的宪法第十三修正案才在全国废除奴隶制，宣言的颁行与奴隶制的全国性废除应区分。"],"references":[{"label":"美国国家档案馆《解放奴隶宣言》原件与转录"}]},
  "ann-chron-world-oceania-1159": {"paragraphs":["十九世纪中叶，澳大利亚各殖民地之间逐步铺设电报线，与亚洲和欧洲的联系仍多依赖轮船。南澳政府推动从阿德莱德通往达尔文的陆上电报线，工程须跨越内陆，运送线杆和器材并设置中继站。施工在不同地段并行，北段受地形与季节变化影响尤甚。","1872年，贯通大陆的线路投入使用，并通过北端海底电缆接入更远的通信网络。信息传递的时间大幅缩短，商业价格和政务消息可以更快交换。工程沿线所依赖的调查、通行和定居改变了原住民社区对土地的使用条件，通信基础设施的成就也有不同群体各自承受的成本。"],"references":[{"label":"澳大利亚国家博物馆「Overland Telegraph」；南澳州立图书馆陆上电报线档案"}]},
  "ann-chron-world-east-asia-0504": {"paragraphs":["七世纪中叶，日本朝廷中苏我氏长期占有重要地位。645年，中大兄皇子与中臣镰足等人在宫廷中杀死苏我入鹿，苏我虾夷随即自尽。政变后皇极天皇退位，孝德天皇即位，王廷迁往难波。中央政治由此进入新的重组过程。","《日本书纪》将其后的改革诏令同整顿土地、赋役、地方行政与户籍相联系。成书于八世纪的《日本书纪》已经处于律令国家的制度环境之中，部分诏令的文字与施行细节需要结合其他史料判断。乙巳之变是一个政治转折点，地方治理改造与律令体系的形成延续了数十年。"],"references":[{"label":"《日本书纪》卷第二十四《皇极天皇》、卷第二十五《孝德天皇》"}]},
  "ann-chron-world-south-asia-0703": {"paragraphs":["葡萄牙王室推动远航，试图建立通往印度洋商品产地和贸易中心的直接航线。达·伽马船队绕过好望角后，沿东非海岸北上，再从马林迪一带借助当地航海经验横渡印度洋，1498年抵达马拉巴尔海岸的卡利卡特。当地港市早已处于阿拉伯、印度等商人参与的海洋贸易网络中。","达·伽马与卡利卡特统治者进行接触，但葡萄牙所带礼物和初次通商条件没有达到预期。此后葡萄牙继续派遣舰队，逐步建立贸易据点和武装控制体系。首次抵达所开启的是欧洲船队经好望角加入印度洋的航线，后来的要塞、征税和海上冲突需要分阶段理解。"],"references":[{"label":"《达·伽马首次印度航行日志》（Roteiro da primeira viagem de Vasco da Gama）"}]},
  "ann-chron-world-southeast-asia-0831": {"paragraphs":["葡萄牙自1511年控制马六甲城，城市依靠海峡航道、港口与堡垒在区域贸易中保持重要地位。十七世纪，荷兰东印度公司以巴达维亚为基地扩张，在同柔佛结盟后围攻马六甲。海上封锁和围城削弱了葡萄牙守军的补给，马六甲于1641年被攻占。","政权更换后，荷兰东印度公司接管城防和港口，并尝试引导商船和贸易收入。区域航运依然经过柔佛、亚齐等港市，商人可以调整交易路线，地方政权也保有谈判空间。应将公司夺取一个港口同它控制整条贸易网络的能力区别开来。"],"references":[{"label":"荷兰国家档案馆 VOC 档案（1.04.02）马六甲来函与决议"}]},
  "ann-chron-world-central-west-asia-0416": {"paragraphs":["旭烈兀军于1258年攻陷巴格达后继续进入叙利亚。蒙古帝国最高统治者蒙哥去世，旭烈兀率主力撤离叙利亚，留下怯的不花等部。埃及马穆鲁克苏丹忽秃思率军北上，拜巴尔参与指挥，双方于1260年在巴勒斯坦的艾因贾鲁交战。","怯的不花战败被杀，马穆鲁克军随即恢复对大马士革等地的控制。战役稳固了埃及与叙利亚之间的新政权布局。蒙古伊儿汗国后来仍多次试图向西推进，叙利亚并未从此脱离战争。马穆鲁克叙事着重突出战胜和统治合法性，可与伊儿汗国方面材料对读。"],"references":[{"label":"伊本·阿卜杜勒·扎希尔《拜巴尔传》；拉施特《史集》旭烈兀相关纪事"}]},
  "ann-chron-world-europe-0160": {"paragraphs":["百年战争期间，英军于1428年围攻奥尔良，试图切断法国王太子查理所控制的卢瓦尔河交通。次年贞德取得觐见查理的机会，随军进入奥尔良。她的到来鼓舞了守军与援军，在数日攻击中，法军接连夺取若干英军据点。","英军于1429年5月撤围。此后的卢瓦尔河战事和向兰斯的进军，使查理七世能够在兰斯加冕，争夺法兰西王位的政治形势随之转变。贞德的具体指挥作用可与诸将的军事行动区分考察，审判证词与围城纪事各自保留了不同的观察角度。"],"references":[{"label":"《贞德定罪审判记录》《贞德平反审判记录》；《奥尔良围城日记》"}]},
  "ann-chron-world-africa-0966": {"paragraphs":["德属东非殖民当局通过税收、劳役和棉花生产政策干预南部各地社区。1905年起，来自不同地方的人群相继攻击殖民机构与生产据点。与金吉基蒂莱相关的「马及」仪式把一些参与者联系起来，各地的行动仍由自身的社会组织和政治诉求推动。","德国军队依靠火器、增援及摧毁粮食供应的手段镇压起义，战争和随后的饥荒造成严重伤亡。不同来源对死亡总数和参加范围估计有差异。殖民政府后来调整部分经济和行政措施，殖民统治继续存在，马及马及战争则成为坦桑尼亚回顾反殖民历史的重要节点。"],"references":[{"label":"坦桑尼亚国家博物馆马及马及战争纪念资料；John Iliffe《坦噶尼喀现代史》"}]},
  "ann-chron-world-americas-1025": {"paragraphs":["1692年初，马萨诸塞殖民地塞勒姆村几名女孩出现异常症状并指认他人施巫，地方纠纷、宗教观念及边境战争带来的不安共同塑造了指控传播的环境。案件从邻里扩散到更多城镇，特别法庭在审理中接受了被告灵体作害之类难以独立验证的证言。","这一年有十九名被告遭绞刑，贾尔斯·科里因拒绝答辩被施加重压致死，另有囚犯死于关押。舆论和当局逐渐质疑证据标准，特别法庭被解散，后续审判与赦免结束了处决。此后多年，一些裁判得到撤销并出现赔偿。理解案件需要同时看指控如何升级，以及殖民司法为何一度认可这类证据。"],"references":[{"label":"弗吉尼亚大学 Salem Witch Trials Documentary Archive；马萨诸塞州档案馆审判文书"}]},
  "ann-chron-world-oceania-1144": {"paragraphs":["1838年6月，一群牧场雇工在新南威尔士的米亚尔溪杀害至少28名原住民，多数是妇女、儿童和老人。杀戮发生在殖民畜牧业扩展、原住民土地被侵占和边疆暴力增加的背景下。当地有人向当局报告，殖民政府随后展开调查并起诉涉案人员。","第一次审判以无罪结束，检方随后就另一名受害者的死亡重新起诉其中七人，七人被判有罪并处决。在殖民边疆同类暴力很少得到追究的环境中，此案成为罕见的司法记录。审判材料可以核对责任及程序，纪念遗址也提醒读者关注受害社区和幸存者的经历。"],"references":[{"label":"澳大利亚国家博物馆「Myall Creek massacre」；新南威尔士州档案馆案件记录"}]},
  "wp-yi-sunsin": {"paragraphs":["李舜臣（1545—1598）出身朝鲜武官，在日本军于1592年渡海入侵前担任全罗左道水军节度使，整顿舰船、兵员和水军供应。战争开始后，他在玉浦、闲山岛等处打击日军船队。朝鲜舰队依靠火炮、编队和对海峡水道的熟悉，利用海上机动牵制日本军海运。","他一度遭罢黜，继任指挥官的舰队在漆川梁遭重创，李舜臣随即复职。1597年，他以重新集合的少量舰船守住鸣梁海峡。次年在露梁与明军水师协同拦截撤退的日本军船队，战斗中阵亡。他留下的《乱中日记》包含军务、家事、天气与疾病记载，为读者理解舰队在战争中的日常压力提供了当事人视角。"],"references":[{"label":"李舜臣《乱中日记》；《宣祖实录》万历援朝相关纪事"}]},
  "wp-babur": {"paragraphs":["巴布尔（1483—1530）出身中亚帖木儿王室，少年继承费尔干纳，在与乌兹别克势力的争夺中多次进出撒马尔罕。失去中亚立足点后，他在1504年取得喀布尔。喀布尔连接中亚与印度北部，给他提供了筹集兵力、维持骑兵和继续扩张的基地。","1526年，他在第一次帕尼帕特之战击败德里苏丹易卜拉欣·洛迪，随后又与以拉纳·桑伽为首的拉杰普特联盟交战。由此建立的北印度统治，后来经历胡马雍失国和复位，才在阿克巴时期得到巩固。巴布尔用察合台突厥语写下回忆录，记录军事决策、地理风物和自身挫折，为了解征服者如何认识中亚与南亚提供了难得的一手记录。"],"references":[{"label":"《巴布尔回忆录》（Bāburnāma）"}]},
  "wp-jayavarman2": {"paragraphs":["阇耶跋摩二世活跃于九世纪初，是吴哥时期早期王权形成中的关键人物。后世碑铭记述他曾在多个地点建立统治，最后把王权与荔枝山一带的仪式联系起来。碑文把802年所举行的仪式描述为维持王权独立和传承的重要起点。","这方碑刻在1052年才立成，叙事也服务于祭司家族追溯自身地位。解读时应把它和同时期遗址、铭文互证，不能把碑中关于「爪哇」的称呼或仪式的性质直接确定为现代地理和制度。吴哥王朝的政治重心由各地据点和人群网络逐渐整合，后来兴建的大规模水利设施及寺院属于后继诸王长期营造的结果。"],"references":[{"label":"柬埔寨 Sdok Kak Thom 碑铭 K.235（1052年）；法国远东学院《柬埔寨铭文》"}]},
  "wp-ashurbanipal": {"paragraphs":["亚述巴尼拔约于前669年继承亚述王位，兄长沙马什·舒姆·乌金同时在巴比伦为王。这一安排维系了不同地区的王室权威，也埋下了兄弟之间的统治冲突。巴比伦后来起兵反抗，亚述经过长时间围困重新控制该城。东面与埃兰的战争则在宫殿浮雕与王室铭文中被大力宣扬。","亚述巴尼拔组织搜集和复制楔形文字文献。尼尼微出土的泥板包括词汇表、占卜资料、医学文本和《吉尔伽美什史诗》等，既供宫廷知识工作使用，也保留了美索不达米亚较早的学术传统。王家铭文刻意彰显统治者的全胜形象，描述征服时须区分有实物或其他记录可核对的行动与宣传措辞。"],"references":[{"label":"大英博物馆亚述巴尼拔宫殿浮雕与「亚述巴尼拔图书馆」泥板档案"}]},
  "wp-socrates": {"paragraphs":["苏格拉底约前469年出生在雅典，曾作为重装步兵服役，后来经常在公共场所与人讨论勇敢、正义和德性。他通过追问说话者的定义和论据，使其发现原先看似自明的信念内部存在矛盾。前399年，他被控不敬城邦神祇、引入新的神灵观念并败坏青年，陪审法庭判处死刑。","他的处境与雅典战败及寡头政治余波有关，不过不能把法庭控罪简单替换成未经证实的单一政治动机。苏格拉底未留下著作，柏拉图和色诺芬的作品以及阿里斯托芬的讽刺剧，分别以辩护、回忆和喜剧塑造了不同形象。读者所熟悉的问答法，经由这些作品的保存才成为后世哲学教学的重要传统。"],"references":[{"label":"柏拉图《申辩篇》《克里同篇》；色诺芬《回忆苏格拉底》；阿里斯托芬《云》"}]},
  "wp-thutmose3": {"paragraphs":["图特摩斯三世年幼即位，早年与哈特谢普苏特共同居于王权体系之内。哈特谢普苏特去世后，他亲自主导多次对西亚的军事行动。米吉多战役中，埃及军穿过通道进入平原，打击结成联盟的地方势力，随后通过围城取得胜利。","卡尔纳克神庙的年代记记录进军、围城和缴获，以献给阿蒙的王权叙事来说明胜利。埃及依靠驻军、贡纳和与各城统治者的关系维持对黎凡特的影响，也继续经营努比亚。纪念铭文对战功的呈现具有宣传性质，可与考古遗迹和其他地区的文书一起观察埃及统治的实际范围。"],"references":[{"label":"卡尔纳克阿蒙神庙《图特摩斯三世年代记》；大都会艺术博物馆古埃及第十八王朝分期"}]},
  "wp-moctezuma": {"paragraphs":["蒙特祖马二世于1502年前后登上墨西加王位，统治中心是湖中的特诺奇蒂特兰。它同特斯科科和特拉科潘结成三方联盟，依靠征服、贡赋和地方政治关系控制中部墨西哥的广大区域。贡赋为首都提供物资，也使周边部分政治共同体产生摆脱控制的动机。","科尔特斯一行在原住民盟友支持下于1519年抵达首都。蒙特祖马接待了他们，随后被扣押，1520年在殖民军撤出前后的冲突中死亡。科尔特斯奏报和后来的纳瓦语口述叙事在其死因等问题上并不相同。应把他放在不同地方政治力量互动中理解，关于他把外来者认作神的说法缺乏同时代的可靠证据。"],"references":[{"label":"佛罗伦萨手抄本第十二卷；埃尔南·科尔特斯《第二封奏报》"}]},
  "wp-tamati": {"paragraphs":["塔马蒂·瓦卡·内内是新西兰北部恩阿普希部族的重要首领。他在十九世纪上半叶参与部族间的征战、贸易和外交，同欧洲商人和传教士往来。1840年怀唐伊会议上，他支持签署条约，希望同英国建立能够约束外来者并维持地方秩序的关系。","1845年北部战争爆发后，内内与霍内·赫克等人处于对立阵营，并同殖民政府方面合作。这些选择也反映毛利首领之间既有的权力关系与不同的政治判断。条约的毛利语文本与英语文本在统治权和首领权威的表述上有重要差异，内内的支持应联系当时的谈判语境理解。"],"references":[{"label":"《新西兰人物传记辞典》「Tāmati Wāka Nene」；新西兰《怀唐伊条约》签名档案"}]},
  "wp-nobunaga": {"paragraphs":["织田信长（1534—1582）出身尾张的地方领主家族，在家族与邻国竞争中逐渐扩展势力。1560年，他在桶狭间击败今川义元。随后取得美浓，并于1568年拥护足利义昭入京都。与义昭关系破裂后，他在1573年将其逐出京都，室町幕府在京都的统治结束。","信长争取控制交通节点、城镇和市场，以兵力与物资集中维持征战，也对比叡山及石山本愿寺等拥有地方军事力量的宗教势力发动战争。1582年，部将明智光秀在京都本能寺袭击信长，信长身亡。其部将丰臣秀吉继续争夺政治主导权，此后全国统一经过新的兼并与联盟才逐步完成。"],"references":[{"label":"太田牛一《信长公记》；日本国立公文书馆「戦国武将」相关藏品"}]},
  "wp-aryabhata": {"paragraphs":["阿耶波多约生于476年。关于他的具体出生地及完整生平，直接史料有限。499年成书的《阿耶波多历数书》用简练的韵文汇集计算规则、历法和天文推算。书中给出了圆周率的近似取值与正弦表，并讨论怎样求解某类整数不定方程。","在天文部分，他以地球自转解释天体每日的视运动，并用天体彼此遮蔽来解释日食和月食。文本的计算框架仍有自身时代的行星模型与历法前提。后世学者通过注释、重算和辩论继承其方法。可以从可复算的算法与天文学解释理解他的贡献，也可由注释传统追踪这些知识怎样传播。"],"references":[{"label":"阿耶波多《阿耶波多历数书》（Āryabhaṭīya）数学篇、历法篇、球学篇"}]},
  "wp-parameswara": {"paragraphs":["帕拉梅斯瓦拉通常被视为马六甲港口政权的早期创建者。他在十四世纪末至十五世纪初活动，先后与苏门答腊及马来半岛的政治网络相关。马六甲坐落在海峡交通要地，港口政权可以依靠停泊、转运和商贸规则聚集不同来源的船商。","明代实录所记满剌加使节、册封和来朝活动显示新兴港口与明廷建立了正式往来。这为地方统治者处理同周边势力的关系增加了外交渠道。关于帕拉梅斯瓦拉的早期迁徙路线、与后继者的称号关系以及本人改宗时间，不同传统记述难以完全互合，宜保留各资料的成书背景。"],"references":[{"label":"马欢《瀛涯胜览·满剌加国》；《明太宗实录》满剌加相关条目；《马来纪年》"}]},
  "wp-hulegu": {"paragraphs":["旭烈兀（约1217—1265）是拖雷之子、蒙哥之弟。受蒙哥派遣，他率蒙古军进入伊朗和西亚，先摧毁以阿拉穆特为代表的尼扎里派堡垒网络，继而在1258年攻陷巴格达。阿拔斯哈里发穆斯台绥木遇害，原有以巴格达为中心的哈里发政治秩序由此终结。","旭烈兀随后向叙利亚推进，蒙哥死后率主力折返，留守军在1260年被马穆鲁克击败。他以伊朗和周边地区为核心建立伊儿汗国，继承者延续这一政权，并在财政、用人与宗教政策上作出调整。志费尼本人曾为旭烈兀效力，拉施特则服务于后期伊儿汗，阅读二者的征服叙事应留意作者所处的政治环境。"],"references":[{"label":"拉施特《史集》旭烈兀纪；志费尼《世界征服者史》"}]},
  "wp-calvin": {"paragraphs":["约翰·加尔文（1509—1564）出生于法国，接受人文主义与法律教育，在宗教改革扩展至法国后离开故乡。1536年，他出版第一版《基督教要义》，并在日内瓦参与教会改革。一度离开日内瓦后，他于1541年返回，通过牧师、教师、长老和执事分工推动改革方案。","日内瓦的宗教纪律由教会组织与城市权力共同塑造，双方也曾在权责上争执。加尔文的神学系统和对新教牧师的培养通过书籍、流亡者及教会联系传播至法国、荷兰、苏格兰等地。当地改革者各有自己的政治处境，同一套神学论述在不同地区产生了不同的组织形式。"],"references":[{"label":"约翰·加尔文《基督教要义》；1541年日内瓦《教会法规》"}]},
  "wp-sundiata": {"paragraphs":["孙迪亚塔是十三世纪马里政治整合中被传颂的王室人物。曼丁口述史以家族竞争、流亡归来以及战胜苏曼古鲁为主线，讲述他的兴起。通行历史叙述常以约1235年前后的基里纳战役作为马里政权形成的一个标志，具体年月与战场细节主要来自时代较晚的重建。","马里逐步整合尼日尔河上游、金产地和区域贸易路线，其影响由后继者继续扩大。孙迪亚塔故事经由职业口述者在不同地方传承，版本之间有明显差别。较晚的阿拉伯语著述保留了马里早期王统线索，可与史诗互读，但无法逐项证实流亡历程和神奇情节。"],"references":[{"label":"D. T. Niane 整理《松迪亚塔：曼丁史诗》；伊本·赫勒敦《历史绪论》之外的《历史大全》苏丹诸王相关记载"}]},
  "wp-hidalgo": {"paragraphs":["米格尔·伊达尔戈（1753—1811）是新西班牙的天主教神父。拿破仑入侵西班牙后，王权合法性争议传到美洲。1810年，克雷塔罗谋划暴露，他在多洛雷斯召集支持者，起义队伍随后迅速扩大。参与者既有地方精英，也有农民和城镇居民，各自的目标并不完全相同。","起义军攻占瓜纳华托等地，并在瓜达拉哈拉发布废奴等命令，但军事组织和供应面临困难。1811年起义军在卡尔德龙桥附近失利，伊达尔戈后来被捕并处死。莫雷洛斯等人继续领导反殖民斗争，墨西哥最终于1821年独立。多洛雷斯号召后来进入国家纪念传统，讲话的确切原文未有可确定的当时记录。"],"references":[{"label":"墨西哥国家总档案馆独立战争文献；伊达尔戈1810年12月6日瓜达拉哈拉废奴法令"}]},
  "wp-honeheke": {"paragraphs":["霍内·赫克是新西兰北部恩阿普希部族首领，1840年在怀唐伊签署条约。殖民政府迁移首都及引入关税后，岛屿湾旧有贸易受到影响，赫克也日益质疑英国在当地行使权力的方式。1844—1845年，他和同伴多次砍倒科罗拉雷卡的旗杆，以挑战殖民权威。","1845年北部战争展开，赫克与卡维蒂等人依靠要塞抵抗殖民军。恩阿普希各支系和首领选择不同，塔马蒂·瓦卡·内内与政府合作。1846年鲁阿佩卡佩卡要塞战斗后，战事转入谈判。赫克从签署条约到武装抵抗的变化，反映出双方对条约权力边界及地方政治秩序的理解发生冲突。"],"references":[{"label":"《新西兰人物传记辞典》「Hōne Heke Pōkai」；新西兰历史网「War in the North」"}]},
  "ann-person-5da0a58319d5": {"heading":"生平与掌权经历","paragraphs":["由琅邪王镇建邺，在王导等协助下联合北来与江南士族，西晋覆亡后先称晋王，后称帝，建立南方晋朝。王敦的军事力量是政治支柱，也构成皇权威胁，王敦起兵后元帝受制，不能把“王与马共天下”理解成双方始终和睦。","司马睿在江南联络北来与本地大族建立晋室政权，先称晋王再称帝；其政治地位依赖新的联盟和地方资源。"],"references":[{"label":"王仲荦《魏晋南北朝史》：东晋门阀政治、北伐与桓玄","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-eastern-jin-d7bc47642b","regimeId":"ce-eastern-jin"}},
  "fujian": {"heading":"生平与掌权经历","paragraphs":["在宫廷政变后掌权，使用大秦天王称号，任用王猛等整顿行政、赋役与军队，在关中建立较强统治基础。灭前燕、前凉及代等政权后，一度统一北方，原有各族军事与贵族网络仍然存在，名义统一并不意味着地方利益全部融为一体。","其对人才的吸收和一定程度的宽容为后世称道，但征服战争与强制迁徙也带来代价。王猛去世后，继续谋求南下统一东晋，383年大军在淝水方向失利。兵力规模的史书记载需谨慎，失败的关键包括指挥、部队构成、地形与士气，不能仅用一个口令或个人轻敌解释。","淝水之后，慕容、姚氏等力量重新独立，苻氏内部也未能有效协调。苻坚离开长安后被姚苌控制并杀害，前秦残余仍延续到苻崇时代。其一生展示了北方政治整合的可能与限度，不能把淝水一战写成其死后所有局势的瞬间终结。"],"references":[{"label":"王仲荦《魏晋南北朝史》第四章：苻秦兴亡与淝水之战","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"}],"ruler":{"id":"ce-former-qin-034a32ffd0","regimeId":"ce-former-qin"}},
  "ann-person-269e59ced498": {"heading":"生平与掌权经历","paragraphs":["秦始皇之子，始皇去世后在赵高、李斯支持下取得继承，前209年为其王年元年。其统治初期大量诛杀宗室及异己，赵高权力上升；陈胜吴广起事后，地方反秦力量迅速发展，章邯虽一度扭转战局，也无法修复中央与军队的信任。胡亥最终被赵高一方逼死，秦的皇帝制度在其身上呈现继承封闭、信息壅蔽与高压统治的危机。","胡亥在始皇去世后的继承安排中即位，其统治与赵高权势、宫廷冲突及秦末起义相交织。后来被逼自杀，子婴继立，秦朝迅速走向终结。"],"references":[{"label":"童书业《春秋史》、杨宽《战国史》及林剑鸣《秦汉史》：秦国政治与统一、秦帝国","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-qin-c602769834","regimeId":"ce-qin"}},
  "liubei": {"heading":"生平与掌权经历","paragraphs":["出自涿郡，自称汉景帝子刘胜之后，早年在地方军事和反黄巾战争中起家。长期依附或联合公孙瓒、陶谦、曹操、袁绍、刘表等势力，失地与迁徙并未中断其军事集团。赤壁前后与孙权结盟，取得荆州部分地区，又进入益州，逐步建立可持续的政权基础。","取得成都和汉中后，先称汉中王，汉献帝禅位于曹丕后又以延续汉朝为名在221年称帝。与孙权一方围绕荆州的矛盾导致关羽败亡，刘备随后东征，222年夷陵战败，退至白帝城一带。次年病逝，托孤诸葛亮等辅佐刘禅。","刘备善于组织政治联盟、维持军事集团，也受到兵源、财政和区域利益的限制。后世小说中的仁君形象不能代替其多次联盟转变、夺取益州与东征决策的具体分析；他的政治生命大部分不在皇帝位上，称帝年数短不等于其统治影响只有两年。"],"references":[{"label":"王仲荦《魏晋南北朝史》：三国政权和蜀汉","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-shu-60ae2cb22c","regimeId":"ce-shu"}},
  "ann-person-89b07678cea0": {"heading":"生平与掌权经历","paragraphs":["刘备去世后继位，前期由诸葛亮主政，继续治理益州、南中与北伐。诸葛亮死后蒋琬、费祎等维系政治和军事运作，姜维后期多次北伐，黄皓等宫廷近臣的影响又与官僚、军事关系交织。263年魏军由邓艾、钟会等进攻，成都防线崩解，刘禅选择投降，被迁往洛阳封安乐公。","其在位四十年，不能只用乐不思蜀故事概括。史书对其性格和决策的评价须与诸葛亮等辅臣长期主持军政、益州资源限制以及后期战争负担联系起来；投降免于城破长期巷战与结束独立政权，两种影响也可同时讨论。"],"references":[{"label":"王仲荦《魏晋南北朝史》：三国政权和蜀汉","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-shu-4b30bf816a","regimeId":"ce-shu"}},
  "v5-lvhou": {"heading":"生平与掌权经历","paragraphs":["起于刘邦早年家庭与战争经历，在楚汉战争中曾被项羽扣留。刘邦称帝后为皇后，参与宫廷与功臣政治。高祖死后为皇太后，惠帝在世时已具有强大影响，惠帝死后公开临朝称制。其统治延续西汉初年恢复生产、稳定秩序的方向，同时扩大吕氏亲族封爵和军事地位。","戚夫人、赵王如意与宗室诸王的遭遇，使传世吕后形象具有强烈宫廷暴力色彩。这些事情必须与继承安排、外戚和宗室竞争一并理解，不能仅当作私人妒恨故事。吕后去世后，周勃、陈平等功臣联合刘氏力量清除诸吕，迎立文帝，后来的史书叙述也受到这一胜利格局的影响。","她是理解汉初实际权力与名义皇位分离的重要人物。吕后没有正式使用皇帝名号，因此在王表中应标临朝执政者，而不能省略，也不能简单改写成与刘邦一样的皇帝。"],"references":[{"label":"林剑鸣《秦汉史》：楚汉战争、西汉政治、王莽改制","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-western-han-697117fb9a","regimeId":"ce-western-han"}},
  "ann-person-c59feb439993": {"heading":"生平与掌权经历","paragraphs":["原名病已，巫蛊之祸后幼年曾处狱中，后来生活于民间与外家环境。刘贺被废后由霍光等迎立，早期须面对霍氏权力及皇后许平君被害等宫廷问题。霍光死后逐步亲政，整顿吏治，强调法律与官员实际治理能力。","其世经营西域，前60年前后设置西域都护；对匈奴既有军事压力，也利用其内部局势开展政治合作，呼韩邪单于来朝成为重要节点。麒麟阁图绘功臣等行动，也在重新组织国家对前代功业的记忆。宣帝在帝国扩张之后较为重视行政效果，但并非放弃严刑和皇权控制，不能简单理解成与武帝完全相反的统治模式。"],"references":[{"label":"林剑鸣《秦汉史》：楚汉战争、西汉政治、王莽改制","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-western-han-de4162a6ac","regimeId":"ce-western-han"}},
  "ann-person-2bad2e14b96f": {"heading":"生平与掌权经历","paragraphs":["武帝死后即位，实际朝政先受杨骏、贾南风及宗王集团操纵。皇太子司马遹遭废杀后，宗王以复仇、辅政等名义互相讨伐，惠帝本人屡被迁动和控制。司马伦一度篡位，随后惠帝复位，仍无法恢复稳定的中央权威。所谓何不食肉等逸闻不能替代对继承、外戚、宗王军队与地方资源的解释。","司马衷在290年继位后经历宫廷和宗王集团反复争夺，皇帝名义被不同力量利用，是八王之乱政治结构的核心位置。"],"references":[{"label":"王仲荦《魏晋南北朝史》：西晋统一、八王之乱与永嘉之乱","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-western-jin-07c9040712","regimeId":"ce-western-jin"}},
  "ann-person-32518a3f6a58": {"heading":"生平与掌权经历","paragraphs":["洛阳陷落后被关中势力拥立，在长安维持西晋残余中央名义。兵力、粮食和地方支持都不足，316年刘曜围攻长安，愍帝出降，西晋作为皇朝的统治结束。其后在平阳被杀；不能把318年的死亡年当作西晋仍在全国统治到318年。","司马邺在洛阳失守后于长安继位，依靠关中残存力量维持西晋朝廷，316年城破被俘，成为西晋终结的关键人物。"],"references":[{"label":"王仲荦《魏晋南北朝史》：西晋统一、八王之乱与永嘉之乱","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-western-jin-c596b00db0","regimeId":"ce-western-jin"}},
  "sunquan": {"heading":"生平与掌权经历","paragraphs":["孙策去世后以年轻继承人身份接掌江东，依靠张昭、周瑜等文武人物，逐步协调地方豪族和军事集团。赤壁之战与刘备一方合作抵御曹操，随后又围绕荆州与刘备长期竞争，219年夺取荆州，220年代在曹魏与蜀汉之间不断调整外交关系。","孙权一度接受魏的吴王封号，后独立建元，229年正式称帝。建业成为政治中心，国家在长江防御、屯田、山越人口控制及地方行政方面持续经营，也组织远航等活动。文献中“夷洲”等地望有争议，不能直接用现代政治地理概念替代考证。","统治后期的太子孙和与鲁王孙霸之争牵连重臣，皇室继承与江东世族关系遭到严重破坏。幼子孙亮继位后，辅政者之间的竞争更加尖锐。孙权建立了延续数十年的南方政权，但战争、人口控制和晚年宫廷政治的代价，须与其开国成就一并说明。"],"references":[{"label":"王仲荦《魏晋南北朝史》：江东孙氏及三国政治","url":"https://github.com/socialismonethree/shiguan-history-atlas/blob/main/CONTENT_GUIDE.md#provided-book","note":"用户提供原书，本站原创整理；不公开原著全文。"},{"label":"教育部《重编国语辞典修订本·中国历代帝王年表》","url":"https://dict.revised.moe.edu.tw/appendix.jsp?ID=2&la=0","note":"核对周至两晋主要君主顺序；西周旧纪年不直接采用。即位、改元、称王/称帝的口径另注。"}],"ruler":{"id":"ce-wu-a767c3ad85","regimeId":"ce-wu"}},
  "zhaokuangyin": {"heading":"生平与掌权经历","paragraphs":["原为后周禁军将领，960年陈桥兵变后即位。通过军政人事和财政制度调整削弱藩镇自主权，先南后北推进统一，灭后蜀、南汉、南唐等国；未完成对北汉、辽的战争便去世。","赵匡胤取得帝位依靠后周禁军核心，因而建立宋朝后首先要处理军队与皇权的关系。他调整禁军、将帅和地方职权，让财政收入更集中于中央，并以文官、通判等参与地方制衡。所谓杯酒释兵权是高度概括的政治故事，不能代替多年制度调整和具体将领去留。","宋初统一需要分阶段整合四川、岭南、江南等拥有不同财政与地方传统的区域。灭国之后，还需重新安置官员、军队和地方精英。太祖未能完成北方战争，其身后由弟赵光义继位，又在宗室关系和历史记忆中留下长久影响。宋代重文局面的形成也经历持续发展，不应归结为太祖一条绝对禁止武力的命令。"],"references":[{"label":"陈振《宋史》","note":"据用户提供的《中国断代史系列·全集》第9册，作者简介，合并文本第119899行附近；用于生平和时代背景，不据活动区间推断生卒。"}],"ruler":{"id":"cl-beisong-6e4e40a8e","regimeId":"cl-beisong"}},
  "ann-person-1c6085042bf2": {"heading":"生平与掌权经历","paragraphs":["宋英宗之子，面对财政、军队与边防问题，任用王安石推动熙宁变法。青苗、免役、市易等法试图重组国家与社会资源关系，也引起持续争论和执行弊病；对西夏用兵未能获得预期成果。","神宗即位时的目标是增强财政和军事能力，以改变边疆压力与中央开支增长的局面。王安石新法试图通过青苗、农田水利、免役、市易等制度，使国家更主动介入资源分配。设计目的、具体执行和地方后果并不总一致，评价必须逐项观察，不能把赞成或反对新法的官员简单划成善恶。","新法也与皇帝用人和朝廷权力有关。王安石多次进退后，部分政策仍被延续，显示变法已超出单一大臣的个人行动。军事方面，熙河经营有所进展，对西夏大举用兵却有重大失利。神宗去世后新旧政策反复，进一步说明改革的延续需要稳定的政治联盟和可持续的执行条件。"],"references":[{"label":"陈振《宋史》","note":"据用户提供的《中国断代史系列·全集》第9册，作者简介，合并文本第119899行附近；用于生平和时代背景，不据活动区间推断生卒。"},{"label":"中国国家博物馆·古代中国（分期与背景概览，非逐条年代核验）","url":"https://www.chnmuseum.cn/portals/0/web/zt/gudai/default.html","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"}],"ruler":{"id":"cl-beisong-f6940dfe1","regimeId":"cl-beisong"}},
  "ann-person-0bc32a286c74": {"heading":"生平与掌权经历","paragraphs":["成长于蒙古诸部竞争环境，经历联盟、战争与部众重组，1206年被推为成吉思汗。此后对西夏、金和中亚发动大规模征服，建立跨地域军事组织；1227年在对西夏战争中去世。国家形成与征服扩张必须同时看到屠杀、迁徙及被征服社会的损失。","铁木真在蒙古诸部竞争中形成强大联盟，1206年建大蒙古国，被尊为成吉思汗，随后发动大规模对外战争，改变欧亚格局。","整合草原军事与政治组织，建立汗国并推进扩张，使蒙古成为新的跨区域力量。","铁木真的成长经历包含父死后部众离散、婚姻和盟誓关系、与札木合等势力的反复联盟及决裂。统一过程中，新军事组织逐步突破原有部落界限，把个人追随关系和战争分配结合起来。1206年的大会因此既是称号授予，也是此前政治军事重组的结果。","大规模征服把欧亚许多地区纳入同一军事政治网络，驿站、使节、技术人员和商旅的流动随之扩大。战争同时破坏城市、农业与人口，不能把后来的交通交流反过来视为战争暴力自然合理的证明。其去世后，宗王分地、汗位选举和各支家族利益成为蒙古帝国延续与分化的关键。"],"references":[{"label":"周良霄《元史》","note":"用户提供的《中国断代史系列·全集》第11册相关朝代章节；本条按世系与史事原创整理。"},{"label":"中国断代史系列·元史","note":"周良霄；依用户提供 Markdown 整理文本正文作原创概述。定位为整理本行号，并非原书页码。整理本存在个别 OCR、纪年和旧有观点问题；本版保留争议说明，不上传原书全文。"},{"label":"中国断代史系列·辽金西夏史","note":"李锡厚、白滨；依用户提供 Markdown 整理文本正文作原创概述。定位为整理本行号，并非原书页码。整理本存在个别 OCR、纪年和旧有观点问题；本版保留争议说明，不上传原书全文。"},{"label":"成吉思汗像","url":"https://www.chnmuseum.cn/zp/zpml/ysp/202012/t20201216_248518.shtml","note":"中国国家博物馆；辅助核对人物生卒、身份及相关背景；不将单一词条视为全部细节的充分证明。"}],"ruler":{"id":"cl-mengyuan-7310bd2bc","regimeId":"cl-mengyuan"}},
  "zhuyoujian": {"heading":"生平与掌权经历","paragraphs":["朱由校之弟，即位后清除魏忠贤集团，试图整顿朝政。面对陕西等地起事、辽东战争和财政困境，频繁用人更易且决策多疑，难以扭转危局。1644年李自成军入北京前在煤山自缢，明在北京的中央政权结束，南明另有延续。","崇祯接手的国家已长期承受辽东军费、财政征收、灾荒和地方社会动荡。清除魏忠贤虽改变宫廷权力格局，却不能自动恢复基层税源和军队供给。对将领和大臣的不信任、频繁更换及对战和的犹疑，又降低朝廷形成稳定政策的能力。","袁崇焕之死、松锦战败和陕西起事不断扩大，使明廷同时面对北方外部军事压力与内部战争。1644年李自成军逼近北京时，征兵、筹饷和调度都已难以挽回。煤山自缢结束了其个人统治，但江南和西南的抗清政权仍继续存在，不能把明末全部历史在北京失守那一刻截断。"],"references":[{"label":"南炳文、汤纲《明史》","note":"据用户提供的《中国断代史系列·全集》第12册，第 12 册　明史（上、下），合并文本第147115行附近；用于生平和时代背景，不据活动区间推断生卒。"}],"ruler":{"id":"cl-ming-56c03e98e","regimeId":"cl-ming"}},
  "zhaogou": {"heading":"生平与掌权经历","paragraphs":["宋徽宗之子，靖康之变时未被金军俘获，在应天府即位，随后辗转江南重建朝廷。前期一度被苗刘兵变迫退，恢复帝位后处理战争、军队与财政；1141年前后推进对金议和并收回将帅兵权，岳飞遇害的政治责任不可回避。","赵构建立南宋，并非带着完整国家机器直接迁往临安，而是在追兵、地方军队和民众迁徙中反复移动。黄天荡、建康等战事和各地抵抗帮助朝廷获得时间，东南财赋、水运和城市资源才逐渐变成新的统治基础。苗刘兵变则表明初年皇帝对军队的控制也并不牢固。","随着南宋政权站稳，高宗越来越重视约束掌兵将领、维持江南财政和议和秩序。绍兴和议使宋金形成对峙，却以政治从属条件和领土放弃为代价，岳飞之死又使君主责任格外沉重。他晚年禅位后仍为太上皇，南宋是否北伐的争论并未因此终结。"],"references":[{"label":"陈振《宋史》","note":"据用户提供的《中国断代史系列·全集》第9册，作者简介，合并文本第119899行附近；用于生平和时代背景，不据活动区间推断生卒。"}],"ruler":{"id":"cl-nansong-616210fac","regimeId":"cl-nansong"}},
  "cixi": {"heading":"生平与掌权经历","paragraphs":["咸丰帝后宫出身、同治帝生母。1861年与慈安、奕訢等通过辛酉政变掌权，先后在同治、光绪幼年垂帘。其政治活动包括洋务时期任用、甲午战后局势、戊戌政变、庚子危机和清末新政。她对晚清决策负有重要责任，但国家衰败也须结合帝国主义侵略、财政、军队及官僚结构分析，不能全化为个人宫廷故事。","慈禧从后宫进入最高政治权力，关键依托同治生母身份、两宫太后制度和与恭亲王奕訢等结成的政治联盟。辛酉政变除去顾命大臣后，垂帘安排仍与军机、地方督抚及王公大臣共同运作；晚清洋务发展因此既有朝廷许可，也依赖地方官僚、工商业和技术人员。","1898年重新掌权、1900年对外宣战与西行，以及1901年以后推行新政，显示其决策并非始终沿一条简单的守旧路线。但政策转向并不能抹去戊戌政变、庚子危机和长期维护皇室权力的责任。评价她，应区分可核对的决策、宫廷宣传、外部观察与后来戏剧化的奢侈轶闻。"],"references":[{"label":"南炳文主编《清史》","note":"用户提供的《中国断代史系列·全集》第13册相关朝代章节；本条按世系与史事原创整理。"}],"ruler":{"id":"cl-qing-e6c8ff872","regimeId":"cl-qing"}},
  "ann-person-df1823521bc9": {"heading":"生平与掌权经历","paragraphs":["醇亲王奕譞之子，同治死后由慈禧选择入继，幼年仍由太后垂帘。亲政后经历甲午战争失败与列强加紧侵略，1898年支持维新，戊戌政变后失去实权并被长期控制。1900年随朝廷西行，晚年病居宫中，1908年去世。","光绪幼年在宫廷内成长，1889年名义亲政后仍处于慈禧的政治影响之下。甲午战争的失败与《马关条约》使改革呼声上升，皇帝试图借维新措施调整官制、教育和经济，康有为等由此接近权力核心；改革支持基础、执行条件与皇权内部分歧却十分薄弱。","戊戌政变后，光绪虽继续保有皇帝称号，却被限制活动，重大政务由慈禧主导。庚子事变和其后的新政发生于这一权力结构中，不能因为诏书仍用光绪年号就归为其独立决策。对于其死亡，现代检测提供砷中毒证据，但具体责任人与过程仍须区分检测结论、历史推断和传闻。"],"references":[{"label":"南炳文主编《清史》","note":"用户提供的《中国断代史系列·全集》第13册相关朝代章节；本条按世系与史事原创整理。"},{"label":"故宫博物院·宫廷事件（明清政治背景概览）","url":"https://www.dpm.org.cn/court/events.html","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"},{"label":"中国国家博物馆·古代中国（分期与背景概览，非逐条年代核验）","url":"https://www.chnmuseum.cn/portals/0/web/zt/gudai/default.html","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"}],"ruler":{"id":"cl-qing-a6b73d790","regimeId":"cl-qing"}},
  "guangxu": {"heading":"生平与掌权经历","paragraphs":["醇亲王奕譞之子，同治死后由慈禧选择入继，幼年仍由太后垂帘。亲政后经历甲午战争失败与列强加紧侵略，1898年支持维新，戊戌政变后失去实权并被长期控制。1900年随朝廷西行，晚年病居宫中，1908年去世。","光绪幼年在宫廷内成长，1889年名义亲政后仍处于慈禧的政治影响之下。甲午战争的失败与《马关条约》使改革呼声上升，皇帝试图借维新措施调整官制、教育和经济，康有为等由此接近权力核心；改革支持基础、执行条件与皇权内部分歧却十分薄弱。","戊戌政变后，光绪虽继续保有皇帝称号，却被限制活动，重大政务由慈禧主导。庚子事变和其后的新政发生于这一权力结构中，不能因为诏书仍用光绪年号就归为其独立决策。对于其死亡，现代检测提供砷中毒证据，但具体责任人与过程仍须区分检测结论、历史推断和传闻。"],"references":[{"label":"南炳文主编《清史》","note":"用户提供的《中国断代史系列·全集》第13册相关朝代章节；本条按世系与史事原创整理。"},{"label":"故宫博物院·宫廷事件（明清政治背景概览）","url":"https://www.dpm.org.cn/court/events.html","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"},{"label":"中国国家博物馆·古代中国（分期与背景概览，非逐条年代核验）","url":"https://www.chnmuseum.cn/portals/0/web/zt/gudai/default.html","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"}],"ruler":{"id":"cl-qing-a6b73d790","regimeId":"cl-qing"}},
  "yangjian": {"heading":"生平与掌权经历","paragraphs":["以北周外戚和辅政大臣身份掌权，581年建立隋，589年完成南北统一。开皇时期整顿户籍赋税与中枢地方机构，并巩固北方边防；晚年废太子杨勇改立杨广，使继承问题成为宫廷政治的重要转折。","杨坚的权力来源并非突然出现：他既属于北周军政贵族，又因女儿成为周宣帝皇后而进入外戚网络。宣帝去世后，杨坚以辅政名义控制中枢，平定尉迟迥等反抗，再完成禅代。由此理解隋的建立，才能看见皇室联姻、地方军队与中央官署怎样共同作用，而非只记一场改朝换代。","统一南北之后，隋朝需要把长期分裂地区纳入共同的行政、赋役和交通体系。开皇年间的大索貌阅、输籍等措施扩大国家掌握户口和征税的能力，律令和州县整顿也为后世留下制度资源。与此同时，强制迁徙、征役与皇权集中仍会给社会造成压力，“开皇之治”应作为综合评价，而不是所有人生活同时改善的保证。"],"references":[{"label":"王仲荦《隋唐五代史》","note":"据用户提供的《中国断代史系列·全集》第8册，作者简介，合并文本第96206行附近；用于生平和时代背景，不据活动区间推断生卒。"},{"label":"中国，公元500—1000年","url":"https://www.metmuseum.org/de/toah/ht/06/eac","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"}],"ruler":{"id":"cl-sui-e28ffc53c","regimeId":"cl-sui"}},
  "xuanzong": {"heading":"生平与掌权经历","paragraphs":["唐睿宗之子，710年参与唐隆政变，后在与太平公主集团的斗争中掌握皇权。开元前期整顿吏治、财政和边防，后期用人、边镇与财政问题日益突出。755年安史之乱爆发，次年离长安入蜀，李亨在灵武即位，玄宗成为太上皇。","玄宗前期与后期之间并非突然由贤转昏的一条道德分界。开元时期姚崇、宋璟等参与治理，税源、官僚和边防制度逐渐调整，朝廷财政与城市社会相当活跃。随着边疆战争延长，节度使所掌军队和辖区不断扩大，中央与边镇之间形成越来越复杂的资源和人事关系。","李林甫、杨国忠等的任用和安禄山的兼镇，与皇帝的决策责任相关，但安史之乱还涉及边军组织、族群联盟、兵源和地方社会。玄宗入蜀后成为太上皇，回长安后的生活受到新朝权力关系约束。理解他的后半生，既要看到盛时积累，也要看到政治军事结构怎样使一场兵变变成全国性战争。"],"references":[{"label":"王仲荦《隋唐五代史》","note":"用户提供的《中国断代史系列·全集》第8册相关朝代章节；本条按世系与史事原创整理。"},{"label":"唐朝，618—907年","url":"https://www.metmuseum.org/es/essays/tang-dynasty-618-906","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"},{"label":"中国，公元500—1000年","url":"https://www.metmuseum.org/de/toah/ht/06/eac","note":"沿用站内已录人物或事件的出处；与本条独立生卒字段分开核对。"}],"ruler":{"id":"cl-tang-561b21c05","regimeId":"cl-tang"}},
  "ann-person-29ae6e74a5eb": {"heading":"生平与掌权经历","paragraphs":["唐顺宗之子，重用裴度等，整顿财政并先后对部分藩镇用兵，淮西之役是重要成果，后世称元和中兴。中央权威有所恢复，却未根除藩镇、宦官和财政矛盾；820年在宫中去世，死因记载涉及宦官政治。","唐宪宗在元和时期强化对部分藩镇的控制，通过战争、任官和财政调度谋求中枢整合，但地方和宦官问题仍然存在。","坚持对淮西等镇用兵，支持裴度等人组织军事行动，使朝廷权力一度获得加强。"],"references":[{"label":"王仲荦《隋唐五代史》","note":"用户提供的《中国断代史系列·全集》第8册相关朝代章节；本条按世系与史事原创整理。"}],"ruler":{"id":"cl-tang-ce0762099","regimeId":"cl-tang"}},
  "ann-person-b6afdc84c4c9": {"heading":"生平与掌权经历","paragraphs":["唐穆宗之子，即位后任用李德裕处理回鹘与昭义军镇等问题。会昌年间大规模毁佛，寺院土地、僧尼和财政关系受到冲击；政策既有财政和政治考量，也造成宗教文化损失。","唐武宗统治时朝廷对寺院、僧尼及相关财产实施大规模限制，宗教政策、军事财政和皇帝信仰取向共同影响施政。","在会昌年间推动裁寺还俗和财产接收，改变宗教机构与国家赋役、土地管理的关系。"],"references":[{"label":"王仲荦《隋唐五代史》","note":"用户提供的《中国断代史系列·全集》第8册相关朝代章节；本条按世系与史事原创整理。"}],"ruler":{"id":"cl-tang-32e91cb4b","regimeId":"cl-tang"}},
  "wp-meiji": {"heading":"生平与掌权经历","paragraphs":["出生于京都，在幕府末期朝廷政治影响上升时成长，1867年继位。次年维新政府以天皇权威重组政权，但政策主要由不同藩出身的领导人、官僚与军人协商推进，不能把废藩置县、财政军制和教育改革写成一位少年君主独力完成。","1889年颁布《大日本帝国宪法》，君主权威与内阁、议会及军队形成新的制度关系。其在位时期，日本先后发动甲午战争与日俄战争，并于1910年吞并朝鲜。认识这一时期既须看到国家能力与工业发展，也须呈现战争、殖民统治和扩张对周边社会的伤害。","明治天皇1912年去世后，由嘉仁继位。其诗歌、诏书和大量纪念图像成为国家记忆的一部分；官方诏令常由相关官员拟定，不能一概当作本人独立撰著。"],"references":[{"label":"宫内厅：庆应三年以后的相关年表","url":"https://www.kunaicho.go.jp/kunaicho/kunaicho/kunaicho-nenpyo.html","note":"即位、改元与宫廷制度；1873年改历前日期须区别旧历，不直接当作公历月日。"},{"label":"日本国立国会图书馆：明治天皇资料展","url":"https://jpsearch.go.jp/en/gallery/ndl-mj7BXzgVE0O","note":"生平与文献图像的机构资料；对颂扬性传记保留其时代与政治语境。"},{"label":"明治神宫：明治天皇及五条誓文","url":"https://www.meijijingu.or.jp/en/about/enshrined/","note":"宗教纪念机构的自述，参考生卒与文本，不直接沿用其颂扬性历史评价。"}],"ruler":{"id":"rs-meiji","regimeId":"rs-japan-modern"}},
  "ann-ce-0104": {"heading":"战役经过与后续","paragraphs":["邯郸被魏军围住后，赵国向齐国求援。若齐军直接赶往赵地，就要迎面碰上庞涓率领的强敌。约公元前353年，田忌与孙膑把目光转向魏国自己的要害：让进攻者先担心身后的安全。","齐军的行动迫使魏军回援，救赵的战场由邯郸城下移到了魏军归途中。待对手赶到桂陵，齐军迎击，使魏军遭到挫败。具体路线与桂陵地望仍有不同解释，但以攻其必救改变敌军部署，是这场战役留给后人的核心线索。","齐国因此牵制了魏国，缓解赵国的危机。“围魏救赵”后来成为兵法中的著名说法：战场上的主动，有时来自迫使对手离开原来占据优势的位置。"],"references":[{"label":"孙膑与围魏救赵","url":"https://study.bjwomen.gov.cn/thought/knowledge/2022/05/07/3788.shtml"}],"battle":"guiling"},
  "ann-ce-0134": {"heading":"战役经过与后续","paragraphs":["上党的归属，把秦赵两国拖进了漫长的消耗。长平一带，廉颇依靠壁垒持守，战争迟迟不能以一次进攻收场。到公元前260年的决战阶段，赵国换上赵括，秦方则由白起指挥，双方的较量由相持转向了危险的机动。","赵军出击后，秦军诱使其离开原有阵地，切断粮道和退路，将其分割包围。围困持续，缺粮使赵军越来越难以维持。赵括在突围中阵亡，余部投降，却未能逃过秦军随后对降卒的大规模杀害。","长平改变了秦赵的力量对比，赵国承受的不只是军队损失，还有人口和社会的创伤。它为秦后续兼并提供了条件，却没有让秦立即完成统一。古籍中的庞大杀降数字及具体处置方式，仍需放在史料争议中审慎理解。"],"references":[{"label":"长平之战","url":"https://www.sxgp.gov.cn/zjgp/lsrw_426/202405/t20240510_1980763.shtml"}],"battle":"changping"},
  "ann-cl-song-liao-xia-jin-1259-326": {"heading":"战役经过与后续","paragraphs":["1259年，蒙哥率领的蒙古军来到合川钓鱼城前。这座扼守交通的山城，是南宋四川防线的一环。王坚和守军依靠山势、工事及城内储备，把一次进攻拖成了难以迅速结束的围困。","蒙古军反复攻击，始终未能攻下城池。蒙哥在四川军中去世后，围攻部队撤离，他的死亡又牵动了汗位继承与各地军事部署。至于他究竟死于疾病还是作战受伤，不同史料并没有给出一致答案。","钓鱼城并未随蒙哥之死退出战争。张珏等继续守御，宋元双方又争夺多年；直到1279年，王立与元方议和后开城。把1259年的围城与此后长期攻防相连，才看得到这座山城如何贯穿南宋最后的岁月。"],"references":[{"label":"独钓中原一座城","url":"https://dfz.cq.gov.cn/zqlswh/fjms_417821/202411/t20241126_13833431.html"}],"battle":"diaoyucheng"},
  "ann-cl-ming-1619-576": {"heading":"战役经过与后续","paragraphs":["1619年，明廷试图用多路进攻遏制后金。杨镐部署四路军向前推进，地图上的合围看似严密，实际却要求相距甚远的军队准确联络、同时行动。努尔哈赤选择利用这一弱点，集中力量逐路应战。","后金先攻击杜松一路，再转向马林、刘綎等部。明军各路难以彼此支援，分进的兵力未能及时合成优势，数路部队先后遭到打击，李如柏所部则撤回。","萨尔浒让后金夺得辽东军事主动，明朝此后的防务压力明显加重。它常被概括为集中兵力战胜分散进攻的战例，但背后也有情报、联络、地形和组织能力的共同作用。"],"references":[{"label":"萨尔浒战役双方兵力考实","url":"https://ccj.pku.edu.cn/Article/DownLoad?id=271016004&type=ArticleFile"}],"battle":"sarhu"},
  "ann-ce-0108": {"heading":"战役经过与后续","paragraphs":["约公元前341年，魏国进攻韩国，齐国再次介入中原争夺。田忌与孙膑率齐军逼近魏国要地，使庞涓不得不回援。决定战局的关键，随后转到了追击与判断之中。","齐军向东撤退。按照传世记载，孙膑逐日减少营灶，让魏军误以为齐军大量逃亡；庞涓轻兵急追，进入马陵附近的伏击地带。魏军遭到重创，庞涓死亡，魏太子申被俘。","魏国的实力受到进一步削弱，齐国的地位则随之上升。减灶诱敌成为后世熟悉的军事故事，但具体地望、细节和规模仍需与史料限制一同阅读。"],"references":[{"label":"马陵古战场","url":"https://www.linyi.gov.cn/info/5389/209786.htm"}],"battle":"maling"},
  "cn-yiling": {"heading":"战役经过与后续","paragraphs":["荆州易手、关羽被杀之后，刘备于221年发动东征。对蜀汉而言，这是一次恢复失地的行动；对孙权而言，守住长江中游就意味着保住江东的安全。陆逊所指挥的吴军，没有急着在蜀军刚推进时决战。","双方相持，蜀军沿山地连营，战线和补给逐渐拉长。到222年，陆逊利用蜀军阵地暴露等条件发动火攻和反击，蜀军败退，刘备退到白帝城，黄权等部的退路也受到战局变化影响。","刘备次年病逝，蜀汉承受了严重损失。孙吴虽保住防线，却仍需要应对曹魏，蜀吴后来也重新修复关系。夷陵由一场争夺荆州的战争，变成了两国重新认识彼此处境的转折。"],"references":[{"label":"夷陵之战，魏蜀吴三国鼎立","url":"https://ycsq.yichang.gov.cn/content-37448-970463-1.html"}],"battle":"yiling"},
  "ann-ce-0364": {"heading":"战役经过与后续","paragraphs":["荆州易手、关羽被杀之后，刘备于221年发动东征。对蜀汉而言，这是一次恢复失地的行动；对孙权而言，守住长江中游就意味着保住江东的安全。陆逊所指挥的吴军，没有急着在蜀军刚推进时决战。","双方相持，蜀军沿山地连营，战线和补给逐渐拉长。到222年，陆逊利用蜀军阵地暴露等条件发动火攻和反击，蜀军败退，刘备退到白帝城，黄权等部的退路也受到战局变化影响。","刘备次年病逝，蜀汉承受了严重损失。孙吴虽保住防线，却仍需要应对曹魏，蜀吴后来也重新修复关系。夷陵由一场争夺荆州的战争，变成了两国重新认识彼此处境的转折。"],"references":[{"label":"夷陵之战，魏蜀吴三国鼎立","url":"https://ycsq.yichang.gov.cn/content-37448-970463-1.html"}],"battle":"yiling"},
  "ann-cl-tang-621-4": {"heading":"战役经过与后续","paragraphs":["621年，李世民围攻洛阳，王世充的处境日益紧迫。窦建德率军来援，唐军顿时需要同时面对一座尚未攻下的城和一支从外线赶来的军队。李世民没有把全部兵力撤向同一个方向，而是留部围城，亲率军队据守虎牢。","虎牢附近的险要地形，限制了援军展开。唐军在对峙中寻找出击机会，最终击败夏军并俘获窦建德。外援失败的消息传到洛阳，王世充也随之出降。","一场作战同时改变了两股割据势力的命运，为唐在中原扩展统治打开道路。不过，各地的军事与政治整合仍将继续，不能把虎牢之胜等同于天下已定。"],"references":[{"label":"李世民及虎牢之战","url":"https://www.ylq.gov.cn/zjyl/mlyl/rwjg/gdmr/1906937790733021186.html"}],"battle":"hulao"},
  "ann-cl-yuan-1363-430": {"heading":"战役经过与后续","paragraphs":["1363年，陈友谅围攻洪都，朱元璋率军救援。争夺长江中下游的两股力量，随之在鄱阳湖水面展开较量。对双方而言，船队不仅是作战工具，也关系到撤退、补给和整个水路网络的控制。","朱陈水师多次交锋，朱军使用火攻，并争夺湖口等关键水道。战斗持续，陈军难以摆脱不利处境，陈友谅在突围交战中中箭身亡，军队随之溃败。","朱元璋由此巩固长江中下游的优势，随后仍需面对其他对手，才走到建立明朝的一步。湖上的胜负之所以重要，是因为它改变了元末各方继续争夺天下的力量基础。"],"references":[{"label":"陈友谅与鄱阳湖之战","url":"https://wlt.hubei.gov.cn/bmdt/ztzl/zshb/201912/t20191226_1799553.shtml"}],"battle":"poyang"},
  "ann-cl-qing-1644-628": {"heading":"战役经过与后续","paragraphs":["1644年春夏，北京已进入李自成手中，吴三桂仍控制着山海关，多尔衮率清军南下。帝都、关隘和军队的归属，使三股力量在山海关一带相遇。吴三桂请求清军援助，多尔衮则要求他归附。","清军加入战斗后，大顺军败退，李自成随后退出北京。多尔衮入京，并推动顺治帝迁都，清廷利用原明官僚和降军接管行政。山海关之胜因此不只是打开一道关门，而是把清朝推向经营中原的新阶段。","这并不意味着全国在1644年同时归清。与南明、农民军余部和地方力量的战争仍将长期继续，征服、制度接续与民众苦难交织展开。理解这一转折，也必须把剃发、圈地及战争暴力放进后续历史。"],"references":[{"label":"原有叙事详解（含具体书目与资料定位）","url":"https://socialismonethree.github.io/shiguan-history-atlas/#relations/qing/events"}],"battle":"cn-qing-entry-battle"},
  "ann-chron-world-europe-0018": {"heading":"战役经过与后续","paragraphs":["公元前490年，波斯远征军在阿提卡的马拉松平原登陆。雅典曾支持伊奥尼亚地区反抗波斯，如今必须面对远征军的进攻。雅典与普拉提亚的重装步兵在附近高地集结，米太亚德等人面临的选择，是继续等待，还是主动迎击。","双方对峙后，希腊步兵发起冲击。中央阵线承受波斯军的压力，两翼却取得进展，继而向中央转进。战斗由正面相撞转为两翼夹击，波斯军退向船队，希腊军随后追击。胜负虽已分出，雅典本城仍面临危险：波斯舰队可能绕海进攻，雅典军于是迅速赶回城外设防。","波斯军最终撤离，雅典守住了城市，也获得了抵抗强敌的信心。不过，这只是希波战争的一个阶段；十年后，更大规模的波斯入侵仍将到来。"],"references":[{"label":"马拉松战役","url":"https://2500years.culture.gov.gr/en/chapters/i-machi-tou-marathona/tmimata-vasis-mnimiou"}],"battle":"marathon"},
  "ann-chron-world-europe-0036": {"heading":"战役经过与后续","paragraphs":["公元前331年，亚历山大的东征军与大流士三世的波斯军在高加米拉附近相遇。大流士选择并平整开阔地形，希望让骑兵与战车充分展开，把马其顿军挡在帝国腹地之外。","开阔的战场也使双方必须同时顾及中央与侧翼。交锋中，亚历山大率骑兵向波斯阵线的间隙突击，大流士随后离开战场，波斯军的抵抗逐渐瓦解。另一侧，帕尔梅尼翁指挥的马其顿左翼仍承受压力，胜利并非全线同时、轻易取得。","亚历山大继而进入巴比伦等重要城市，阿契美尼德王朝的中央军事力量受到决定性打击。帝国的灭亡与新统治的建立却仍需要后续行动，不能把整个政治转变都压缩在这一天之内。"],"references":[{"label":"Gaugamela","url":"https://academic.oup.com/edited-volume/61673/chapter-abstract/548938886?login=false"}],"battle":"gaugamela"},
  "ann-chron-world-europe-0044": {"heading":"战役经过与后续","paragraphs":["公元前216年，汉尼拔已率军深入意大利。面对罗马集结的大军，他在坎尼附近迎战。罗马方面希望凭密集步兵的强力推进，一举压垮迦太基军中央，结束眼前的危机。","汉尼拔把伊比利亚与高卢士兵置于中央，非洲步兵安排在两翼。罗马步兵向前挤压时，迦太基中央逐渐向后弯曲，罗军深入其中，却未能把对方阵线彻底击穿。与此同时，迦太基骑兵压制了两侧的罗马骑兵，使步兵侧后方失去保护。","随后，两翼的非洲步兵转向夹击，获胜的骑兵又从后方返回。原本用来突破的密集阵形，此时让罗马士兵难以转身和脱离。包围圈内的战斗造成惨重损失，执政官保卢斯战死，汉尼拔取得了著名的战场胜利。","坎尼没有使罗马退出战争。罗马逐渐以更持久的消耗与资源动员应对汉尼拔，最终赢得第二次布匿战争；这也使坎尼成为理解“战术大胜为何未必带来战略胜利”的重要案例。"],"references":[{"label":"坎尼战役","url":"https://www.history.com/articles/ancient-romes-darkest-day-the-battle-of-cannae"}],"battle":"cannae"},
  "ann-chron-world-south-asia-0705": {"heading":"战役经过与后续","paragraphs":["1526年，喀布尔统治者巴布尔进入北印度，与德里苏丹易卜拉欣·洛迪争夺统治权。4月21日，双方在帕尼帕特相遇，巴布尔需要让规模有限的军队在正面冲击中站稳脚跟。","他把车垒与火炮、火枪结合起来，构成有防护的阵地，同时运用骑兵进行侧翼机动。洛迪军进攻时，阵地火力与侧面的威胁相互配合，打乱了其攻势。洛迪战死，军队溃散，德里与阿格拉随后落入巴布尔之手。","这场胜利成为莫卧儿帝国在北印度立足的重要起点。不过，夺下政治中心只是开始，巴布尔及其继承者仍需通过后续战争和治理巩固新政权。"],"references":[{"label":"第一次帕尼帕特战役","url":"https://panipat.gov.in/first-battle/"}],"battle":"panipat-1526"},
  "ann-chron-world-south-asia-0711": {"heading":"战役经过与后续","paragraphs":["16世纪中叶，毗奢耶那伽罗帝国与德干诸苏丹国长期争夺南印度的地区利益。1565年，苏丹国结成联盟，与实际掌权的拉马·拉亚所率军队在克里希纳河以南地区会战。","德干联军的火炮和骑兵在交锋中发挥作用，拉马·拉亚被俘并遭杀害，毗奢耶那伽罗军随之溃散。战斗之后，帝国都城遭到洗劫，军事失利迅速转化为政治与城市生活的重创。","塔利科塔改变了南印度的力量格局，但王朝残余随后仍在其他城市延续。关于倒戈、兵力和战场位置的不同说法，应与这条较为清楚的兴衰脉络分开辨认。"],"references":[{"label":"塔利科塔战役","url":"https://ignca.gov.in/Asi_data/75359.pdf"}],"battle":"talikota"},
  "ann-chron-world-south-asia-0728": {"heading":"战役经过与后续","paragraphs":["1761年，向北扩张的马拉塔势力，与艾哈迈德沙·杜兰尼及其盟友在帕尼帕特对峙。漫长的等待不断消耗马拉塔军的补给，萨达希夫拉奥·巴乌最终选择通过决战摆脱困境。","1月14日，双方展开激烈交锋。马拉塔军试图打破局面，杜兰尼方面则运用骑兵机动与预备队反击。在难以持续补给的压力下，马拉塔军逐渐失去支撑，最终溃败，双方都付出沉重代价。","北印度的政治格局因此重新调整，马拉塔遭受严重挫折，却没有永久退出历史舞台。其后马拉塔仍重新崛起，东印度公司的扩张也经历了更长过程，并非由此役直接、立即完成。"],"references":[{"label":"帕尼帕特历史","url":"https://panipat.gov.in/history/"}],"battle":"panipat-1761"},
  "ann-chron-world-europe-0257": {"heading":"战役经过与后续","paragraphs":["1805年10月21日，法西联合舰队驶出加的斯后，在特拉法尔加角附近遭遇英国舰队。纳尔逊希望通过一场海战摧毁对方主力，使英国海上安全获得更牢固的保障。","他没有让舰队与敌舰纵列平行对射，而是分成两列切入敌阵。纳尔逊与科林伍德分别带队，将法西舰队分割成难以彼此支援的部分，近距离炮战随之展开。英国舰队渐占上风，纳尔逊却在旗舰上中弹，未能活着见到战斗的终局。","法西联合舰队损失惨重，英国海上优势进一步巩固。然而，同年的欧洲大陆仍由拿破仑赢得重大胜利，海上的胜负与陆上的战争并未同步结束。"],"references":[{"label":"特拉法尔加海战背景","url":"https://www.rmg.co.uk/stories/maritime-history/battle-trafalgar-background"}],"battle":"trafalgar"},
  "ann-chron-world-europe-0045": {"heading":"战役经过与后续","paragraphs":["罗马将领西庇阿把战争带到北非后，迦太基召回在意大利征战多年的汉尼拔。公元前202年，两位将领在今突尼斯境内迎来决战，第二次布匿战争的重心也从意大利转回迦太基的家门。","汉尼拔投入战象和步兵，罗马军则通过阵形间隙等办法应对战象冲击，双方步兵继而激战。战斗后期，西庇阿与马西尼萨的罗马、努米底亚骑兵发挥重要作用，迦太基军最终崩溃。","迦太基接受和平条件，战争加速走向结束，罗马在西地中海的优势得以确立。扎马与坎尼遥相呼应：曾在意大利取得辉煌胜利的汉尼拔，最终未能阻止战争在本国土地上以失败收场。"],"references":[{"label":"扎马战役古典文献研究","url":"https://thescholarship.ecu.edu/server/api/core/bitstreams/d35158af-cba0-424f-9ce5-1644e1c42931/content"}],"battle":"zama"},
  "ann-chron-world-europe-0157": {"heading":"战役经过与后续","paragraphs":["1415年，亨利五世攻占阿弗勒尔后率英军向加来撤行，法军前来拦截。10月25日，双方在阿金库尔附近相遇，英军借树林之间的狭窄地形布阵，长弓手在前方设置木桩防护。","法军重装部队向前推进时，泥泞与拥挤使行动更加困难。弓箭、木桩和近距离搏斗相互作用，进攻最终受挫，大批法国贵族阵亡或被俘。胜利的另一面同样需要记住：英军在战斗中杀害了部分俘虏。","亨利五世随后返回英格兰，胜利增强了他继续对法作战的能力，却没有结束百年战争。理解阿金库尔，需要把地形、指挥和近战与长弓一并考虑，而不是用一种武器解释全部胜负。"],"references":[{"label":"阿金库尔战役","url":"https://www.musee-armee.fr/ExpoChevaliersBombardes/battle-agincourt.html"}],"battle":"agincourt"},
  "ann-chron-world-europe-0191": {"heading":"战役经过与后续","paragraphs":["奥斯曼与威尼斯等力量在地中海的冲突，因塞浦路斯战争进一步升级。西班牙、威尼斯、教皇国等结成神圣同盟，1571年10月7日，唐·胡安所率舰队在帕特雷湾迎战阿里帕夏的奥斯曼舰队。","两支桨帆舰队正面交锋，炮击之后常常接上接舷与近战。战线中央，同盟舰队击败奥斯曼旗舰，其他部位的战斗也逐步向同盟有利的方向发展，奥斯曼舰队遭到严重损失。","勒班陀提高了同盟声望，却没有永久终结奥斯曼海上力量。联盟随后出现分裂，奥斯曼则重建舰队，继续维持东地中海影响力；海战的大胜与长期政治收获之间，仍有明显距离。"],"references":[{"label":"勒班陀海战","url":"https://catalogo.museidigenova.it/oggetti/190055-la-battaglia-di-lepanto?i=32"}],"battle":"lepanto"},
  "ann-chron-world-europe-0258": {"heading":"战役经过与后续","paragraphs":["1805年，第三次反法同盟试图遏止拿破仑在欧洲的扩张。12月2日，法军与俄奥联军在奥斯特里茨附近会战，双方的部署围绕中央普拉岑高地和法军右翼展开。","联军把力量向法军右翼投入，中央高地的兵力随之减弱。拿破仑抓住这一变化，命苏尔特所部向高地进攻。法军夺取关键位置后，把联军阵线分割开来，迫使对方后撤，战局由联军主动进攻转为法军控制。","奥地利随后与法国签订普雷斯堡和约，第三次反法同盟加速瓦解，中欧政治格局发生变化。胜利没有终结欧洲战争，却使拿破仑在这一阶段取得了显著优势。"],"references":[{"label":"奥斯特里茨战役编年","url":"https://www.napoleon.org/en/history-of-the-two-empires/timelines/austerlitz-2-december-1805-a-timeline"}],"battle":"austerlitz"},
  "ann-chron-world-europe-0121": {"heading":"战役经过与后续","paragraphs":["1071年，拜占庭与塞尔柱突厥势力在安纳托利亚东部的边疆冲突不断扩大。皇帝罗曼努斯四世亲自率军，与苏丹阿尔普·阿尔斯兰的军队在曼齐刻尔特交战，双方争夺帝国东部的安全与主动权。","拜占庭军在战斗中失败，皇帝被俘，使这次军事失利产生了超出战场的政治震动。有关兵力、部队行动和指挥分歧的具体叙述，在不同史料中存在差异，不宜把一种完整的战术重建当作定论。","战后，突厥势力进入安纳托利亚并定居的进程加快，拜占庭东部防线受到严重打击。但这一转变持续多年，并不是一场胜利便立即完成了对整个地区的征服。"],"references":[{"label":"塞尔柱时期的安纳托利亚","url":"https://www.metmuseum.org/es/essays/the-art-of-the-seljuq-period-in-anatolia-1081-1307"}],"battle":"manzikert"},
  "ann-chron-world-americas-1038": {"heading":"战役经过与后续","paragraphs":["1777年，伯戈因率英军从加拿大南下，试图控制哈得孙河谷，把北美起义地区分隔开。盖茨等指挥的美军在贝米斯高地设防，南下的英军由此遇到难以轻易绕过的阻力。","9月19日，弗里曼农场战斗后，英军虽占住战场，却损失较大。10月7日，贝米斯高地的战斗再度展开，美军在阿诺德、摩根等参与的作战中取得进展，英军被迫退向萨拉托加，期待中的援军又未能及时到达。","10月17日，伯戈因率军投降。由两次主要会战、包围和投降组成的这一战役，增强了独立阵营的外交地位，促进法国承认美国并与之结盟，使战争进一步走向国际化。"],"references":[{"label":"萨拉托加战役年表","url":"https://www.nps.gov/sara/learn/historyculture/campaign-timeline.htm"}],"battle":"saratoga"},
  "ann-chron-world-americas-1058": {"heading":"战役经过与后续","paragraphs":["1819年，玻利瓦尔率独立军越过安第斯山脉，向新格拉纳达的政治中心推进。8月7日，军队在博亚卡桥附近遇到巴雷罗率领的保王军，行军途中的队形分散给了独立军进攻的机会。","玻利瓦尔与桑坦德等组织截击，使保王军难以把分散的部队重新合为完整防线。交战后，巴雷罗与大量士兵被俘，保王军失去继续阻挡独立军进入圣菲的能力，副王随后离开。","独立军进入圣菲，即今波哥大，新格拉纳达独立进程由此跨过关键节点。但南美其他地区的战争仍在继续，博亚卡打开了这一地区的局面，并没有一次结束全部独立战争。"],"references":[{"label":"博亚卡桥与独立战争","url":"https://enciclopedia.banrepcultural.org/Puente_de_Boyac%C3%A1"}],"battle":"boyaca"},
  "ann-chron-world-americas-1062": {"heading":"战役经过与后续","paragraphs":["1824年，秘鲁独立战争进入关键阶段。玻利瓦尔任命苏克雷统军，独立军在阿亚库乔附近迎战西班牙保王军，要把前期的军事进展转化为更稳固的独立局面。","12月9日，苏克雷指挥部队与占据高地的保王军交锋。保王军防线在作战中崩溃，副王拉塞尔纳所率军队失败，双方随后签署军事投降协议。玻利瓦尔对战局具有重要领导作用，但这一天的现场指挥是苏克雷。","阿亚库乔巩固了秘鲁独立，也是西属美洲大陆独立战争的重要转折。西班牙残余据点仍存在一段时间，战役的决定性意义不应被写成所有抵抗在当天同时消失。"],"references":[{"label":"阿亚库乔战场","url":"https://whc.unesco.org/en/tentativelists/6413/"}],"battle":"ayacucho"},
  "ann-chron-world-africa-0952": {"heading":"战役经过与后续","paragraphs":["1879年，英国军队入侵祖鲁王国，企图扩大在南部非洲的统治。1月22日，切姆斯福德分兵之后，伊散德尔瓦纳的英军营地防御相对薄弱，祖鲁军的进攻直指这一处漏洞。","恩钦瓦约等现场指挥者运用机动与包围战法向营地进逼。英军防线被拉长，补给也出现困难，最终难以阻止祖鲁军突入，营地遭到毁灭性打击。祖鲁国王塞奇瓦约与现场指挥官的角色，需要分开理解。","这场胜利迫使英国调整部署，成为非洲军队抵抗殖民入侵的显著战例。然而英军随后增援并继续进攻，祖鲁王国最终仍在战争中失败，局部胜利没有改变双方长期资源差距带来的压力。"],"references":[{"label":"祖鲁战争","url":"https://www.nam.ac.uk/explore/zulu-war"}],"battle":"isandlwana"},
  "ann-chron-world-africa-0962": {"heading":"战役经过与后续","paragraphs":["1898年9月，英埃军已经逼近马赫迪国家的首都地区。阿卜杜拉集结军队迎战，试图阻止基奇纳继续推进，双方于2日在恩图曼附近交锋。","马赫迪军发动进攻时，面对的是步枪、机枪与火炮组成的密集火力。英埃军在阻击之后继续向城市推进，马赫迪军承受严重伤亡，难以维持抵抗，阿卜杜拉随后撤离。","恩图曼被占领，马赫迪国家的军事力量遭到重创，苏丹随后进入英埃统治。双方部队中都包括本地士兵，战争不能被简化为两个民族的对撞；军事技术差距带来的巨大伤害，以及其后的殖民统治，同样是这场战役的核心内容。"],"references":[{"label":"埃及与苏丹战事","url":"https://www.nam.ac.uk/explore/egypt-and-sudan"}],"battle":"omdurman"},
  "ann-ce-0102": {"heading":"专题连读 · 商鞅变法与秦国制度重组","paragraphs":["战国各国不断调整土地、赋税和兵役制度，秦孝公希望改变秦相对东方强国的不利处境。来自卫国的商鞅进入秦廷，将强化君主权力与提高耕战能力结合起来。","改革通过编户、什伍、连坐和奖惩，把家庭置于更直接的国家管理下；奖励农业和军功，限制依靠血缘而不立功取得地位的旧贵族。这些办法使资源更易转化为军队与税收。","后续改革涉及县制、户籍、家庭分异和土地关系，迁都咸阳也服务于新政治中心的建设。原有制度并非全部由商鞅首创，而是在其主持下重组、强化并形成较稳定的政策组合。","秦的动员和行政能力增强，为之后扩张提供条件；秦孝公死后商鞅被杀，但重要制度未随其个人败亡而全部取消。","理解商鞅变法应兼看富国强兵的成效与严刑、连坐和国家控制的社会成本。它是从贵族政治向地域官僚治理转变的典型案例，也说明国家能力增长不等于普通人获得更多自由。","《商君书》包含不同时期材料，不能逐篇都算商鞅亲笔；传统两次变法纪年是梳理框架，不代表全部制度只在两年内完成。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第65754、67950—68530行；据相关正文综合概述，年代争议见正文"}]},
  "ann-ce-0110": {"heading":"专题连读 · 商鞅变法与秦国制度重组","paragraphs":["战国各国不断调整土地、赋税和兵役制度，秦孝公希望改变秦相对东方强国的不利处境。来自卫国的商鞅进入秦廷，将强化君主权力与提高耕战能力结合起来。","改革通过编户、什伍、连坐和奖惩，把家庭置于更直接的国家管理下；奖励农业和军功，限制依靠血缘而不立功取得地位的旧贵族。这些办法使资源更易转化为军队与税收。","后续改革涉及县制、户籍、家庭分异和土地关系，迁都咸阳也服务于新政治中心的建设。原有制度并非全部由商鞅首创，而是在其主持下重组、强化并形成较稳定的政策组合。","秦的动员和行政能力增强，为之后扩张提供条件；秦孝公死后商鞅被杀，但重要制度未随其个人败亡而全部取消。","理解商鞅变法应兼看富国强兵的成效与严刑、连坐和国家控制的社会成本。它是从贵族政治向地域官僚治理转变的典型案例，也说明国家能力增长不等于普通人获得更多自由。","《商君书》包含不同时期材料，不能逐篇都算商鞅亲笔；传统两次变法纪年是梳理框架，不代表全部制度只在两年内完成。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第65754、67950—68530行；据相关正文综合概述，年代争议见正文"}]},
  "ann-ce-0168": {"heading":"专题连读 · 陈胜吴广起义","paragraphs":["秦统一后持续征发人力，修筑、戍守与战争造成沉重负担。始皇去世后的继承争夺及二世统治加深危机；陈胜、吴广带领戍卒反抗，正是在长期不满中找到爆发点。","据《史记》叙述，一行戍卒途中遇雨失期，陈胜、吴广利用扶苏、项燕等政治符号组织群众，杀死押送军官，在大泽乡起兵。鱼书狐鸣属于史书记载的动员情节，应与可独立验证的事实层次区分。","义军迅速攻占多处县城，进入陈县后建立张楚政权，并派兵向关中及各地发展。扩张速度很快，但内部指挥、各支军队之间的协调与后续补给存在困难，秦将章邯的反击改变战局。","陈胜政权最终失败，陈胜、吴广相继身亡；各地反秦战争却继续扩大，项羽、刘邦及恢复旧国号的势力成为后续竞争者。","起义撼动了秦的基层控制，使统一帝国陷入全面战争。其意义不应仅以起义军是否最终取得皇位衡量；它揭示严密行政体制在过度征发和政治危机下同样可能迅速失效。","“失期当斩”是传世叙事，出土秦律所见对不同征发、天气和迟到情形的处理更复杂，不能概括为一切遇雨误期者皆死。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第75153—75200行；据相关正文综合概述，年代争议见正文"}]},
  "ann-ce-0209": {"heading":"专题连读 · 推恩令削弱诸侯封地","paragraphs":["七国之乱后，诸侯王军事力量已受削弱，但大封国及其财力仍影响中央统治。直接大幅削地容易激起抵抗，武帝政府因此采用更能分化诸侯内部利益的办法。","主父偃建议允许诸侯王把封地分给除嫡长子以外的其他子弟，称为推恩。表面上是让王室子孙分享利益，实际把大王国逐代分割为较小单位，使更多子弟的地位取决于中央的册封。","新封列侯及其封地与原王国的关系受到重新安排，中央通过郡县官僚系统加强控制。这一过程与对王国官制的限制、对违法诸侯的处置及其他削藩措施共同进行。","大封国可以支配的人口、土地和财政逐渐缩小，中央与地方的权力结构趋于有利于皇帝与郡县体系。","推恩令显示帝国治理并不只有战争和直接剥夺，也可以借继承制度改变地方势力结构。它把宗室内部的继承诉求转化为分割封国的动力，成为理解汉代中央集权发展的典型制度案例。","推恩不是一纸诏书立即消除所有王国；不同王国的分割时间和幅度不同，须与前后政策连续观察。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第76040—76160行；据相关正文综合概述，年代争议见正文"}]},
  "ann-ce-0218": {"heading":"专题连读 · 张骞出使西域","paragraphs":["汉武帝最初希望联络被匈奴击败西迁的大月氏，形成对匈奴的夹击。朝廷对遥远西域了解有限，寻找盟友同时也是获取地理、政治和交通知识的探索。","张骞以郎官身份应募，率随从西行，途中被匈奴长期扣留，脱身后经过大宛等地抵达大月氏。大月氏已经安居新地，不愿按汉朝的设想发动战争，最初的军事结盟目标没有实现。","张骞返回后报告中亚各地的物产、道路与政治情况。此后他再次出使乌孙，并分遣副使与多地联系；与河西经营、商旅活动共同作用，汉朝与中亚的使节往来显著增加。","出使带回的信息推动了汉朝对西域政策的形成，外交目标从寻找单一盟友发展为更广泛的通使与交往网络。","“凿空”的意义在于扩大国家层面的知识和联系，而非张骞之前欧亚大陆从无交流。后来所谓丝绸之路由众多绿洲居民、商人、使节和政治力量共同维系，不是一次出使开成的一条固定道路。","第二次行程的起讫纪年在研究中略有差别；张骞不是所有西来作物和技术的唯一引进者，不宜将每种物产都归到他名下。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第76742、77086—77135行；据相关正文综合概述，年代争议见正文"}]},
  "ann-ce-0504": {"heading":"专题连读 · 北魏均田与三长制","paragraphs":["北魏统一北方后，需要恢复人口与农业，扩大国家对户籍和赋役的掌握。战乱、豪强荫附和土地占有差异，使许多人并不直接登记于政府体系。","均田政策按年龄、身份和土地种类安排授受，试图让编户获得耕作条件并承担稳定赋役。它并不把全国所有私人土地收归国家，也不是现代意义的平均分地。","三长制通过邻、里、党等基层组织调查户口、征发赋税，减少豪强隐匿人口的空间。两项政策相互配合：土地与生计安排服务于国家登记，而户籍又是分配和征敛的依据。","国家直接掌握的人口与税役基础扩大，为北魏恢复生产及后续迁都改革创造条件，但地方势力与土地兼并并未因此彻底消失。","均田和基层编制影响北朝、隋唐制度，说明土地政策、家庭登记和政治权力不可分开理解。对农民而言，获得耕种机会与承担税役同时发生，不能只写政策惠民而不写责任。","均田的土地来源、所有权性质和实际授田程度有研究争论；原书村社阶段论属于特定解释，不把它写作唯一共识。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"用户提供合并整理本第89424—89520行，相应正文综合概述"}]},
  "cn-ns-sui": {"heading":"专题连读 · 杨坚建隋与灭陈","paragraphs":["北周灭北齐后，北方已具备较大整合基础。杨坚掌握北周政权并建隋，继续整顿制度和军事；南方陈朝的政治资源与军事防御则日渐处于弱势。","隋先稳定北方和边境，准备舟师与渡江据点，再沿长江上、中、下游多路进军。杨广、杨俊、杨素等分别负责不同方向，战略是使陈无法在一个渡口集中全部力量。","隋军突破长江防线后逼近建康，陈军抵抗失利，陈后主被俘。战后隋接收南方行政与户籍，但各地仍有反抗和制度磨合，政治统一不是社会差异立即消失。","自西晋末年以来的长期南北分立基本结束，隋得以在更大范围内推行官制、法律、户籍和交通整合。","隋统一为唐代制度和经济联系奠定重要基础。其意义既在结束分裂战争，也在重新连接北方政治中心与江南物资区域；此后的运河建设正与这一新格局密切相关。","南北朝结束采用589年；隋并非把此前所有地区一日全部纳入相同管理，部分地方的整合和反抗仍延续多年。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第96480—96580行；据相关正文综合概述，年代争议见正文"}]},
  "ann-ce-0578": {"heading":"专题连读 · 杨坚建隋与灭陈","paragraphs":["北周灭北齐后，北方已具备较大整合基础。杨坚掌握北周政权并建隋，继续整顿制度和军事；南方陈朝的政治资源与军事防御则日渐处于弱势。","隋先稳定北方和边境，准备舟师与渡江据点，再沿长江上、中、下游多路进军。杨广、杨俊、杨素等分别负责不同方向，战略是使陈无法在一个渡口集中全部力量。","隋军突破长江防线后逼近建康，陈军抵抗失利，陈后主被俘。战后隋接收南方行政与户籍，但各地仍有反抗和制度磨合，政治统一不是社会差异立即消失。","自西晋末年以来的长期南北分立基本结束，隋得以在更大范围内推行官制、法律、户籍和交通整合。","隋统一为唐代制度和经济联系奠定重要基础。其意义既在结束分裂战争，也在重新连接北方政治中心与江南物资区域；此后的运河建设正与这一新格局密切相关。","南北朝结束采用589年；隋并非把此前所有地区一日全部纳入相同管理，部分地方的整合和反抗仍延续多年。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第96480—96580行；据相关正文综合概述，年代争议见正文"}]},
  "ann-cl-tang-627-12": {"heading":"专题连读 · 贞观时期的恢复与治理","paragraphs":["隋末唐初长期战争造成户口流散和生产损害。唐太宗的统治并非接手一个已经全面繁荣的社会，而是在国家基本统一后继续恢复农业、户籍、财政和官僚秩序。","朝廷任用房玄龄、杜如晦、魏徵等，重视官员选任、听取谏议和审慎用刑，并在前代基础上修订律令。减轻部分征发、保证农时与节用，是恢复生产和稳定编户的重要政策方向。","同时，唐积极处理突厥等边疆势力和对外战争，扩大政治影响。国家资源并非只用于休养，晚期的高句丽战争等也带来成本，因此不能把整个贞观时期写成无矛盾的太平画卷。","人口、农业和财政逐步恢复，朝廷统治趋于稳固，形成后世称颂的“贞观之治”，为高宗及开元时期的发展提供条件。","其历史地位在于战争后重建与制度化治理的结合。“纳谏”故事可以帮助理解君臣政治，但更应连接律令、行政、赋役和地方执行，避免把盛世归结为皇帝个人品德。","户籍数字反映登记能力和战后恢复，不能直接等同真实总人口；《贞观政要》等有劝诫与典范书写目的，须与实际政策互看。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第97716—97810行；据相关正文综合概述，年代争议见正文"}]},
  "ann-cl-tang-629-13": {"heading":"专题连读 · 玄奘西行与译经","paragraphs":["中国佛教已形成多种经论与解释传统，译本差异使教义问题难以解决。玄奘希望直接到佛教学术重镇研习原典，因此西行不仅是旅行，更是有明确问题意识的求学。","玄奘经过河西和中亚多个地区，了解不同国家、交通与宗教情形，最终进入印度，在那烂陀等地研习佛学。他与当地学者交流，学习语言和论证方法，收集大量佛教文献。","645年回到长安后，他在朝廷支持下组织系统译经，分工包括译出、证义、缀文和校订等。由其见闻口述、辩机编次的《大唐西域记》，保存了沿途政区、习俗与佛教状况的重要资料。","大量经论被译为汉文，推动唯识学等学术发展，并为中国与南亚、中亚文化联系留下内容丰富的记载。","玄奘的贡献是求学、翻译、知识整理与跨文化沟通的结合。其行旅也说明唐代世界由多条政治和宗教网络连接，而非一个人进入无人之地；沿途居民、僧侣与统治者提供了重要帮助。","出发年份及生年有不同研究口径；《西游记》是后世小说，不是行程档案，《西域记》对不同地区也含亲见与转闻之别。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第112191—112193、112300—112430行；据相关正文综合概述，年代争议见正文"}]},
  "ann-cl-tang-645-23": {"heading":"专题连读 · 玄奘西行与译经","paragraphs":["中国佛教已形成多种经论与解释传统，译本差异使教义问题难以解决。玄奘希望直接到佛教学术重镇研习原典，因此西行不仅是旅行，更是有明确问题意识的求学。","玄奘经过河西和中亚多个地区，了解不同国家、交通与宗教情形，最终进入印度，在那烂陀等地研习佛学。他与当地学者交流，学习语言和论证方法，收集大量佛教文献。","645年回到长安后，他在朝廷支持下组织系统译经，分工包括译出、证义、缀文和校订等。由其见闻口述、辩机编次的《大唐西域记》，保存了沿途政区、习俗与佛教状况的重要资料。","大量经论被译为汉文，推动唯识学等学术发展，并为中国与南亚、中亚文化联系留下内容丰富的记载。","玄奘的贡献是求学、翻译、知识整理与跨文化沟通的结合。其行旅也说明唐代世界由多条政治和宗教网络连接，而非一个人进入无人之地；沿途居民、僧侣与统治者提供了重要帮助。","出发年份及生年有不同研究口径；《西游记》是后世小说，不是行程档案，《西域记》对不同地区也含亲见与转闻之别。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第112191—112193、112300—112430行；据相关正文综合概述，年代争议见正文"}]},
  "ann-chron-world-south-asia-0677": {"heading":"专题连读 · 玄奘西行与译经","paragraphs":["中国佛教已形成多种经论与解释传统，译本差异使教义问题难以解决。玄奘希望直接到佛教学术重镇研习原典，因此西行不仅是旅行，更是有明确问题意识的求学。","玄奘经过河西和中亚多个地区，了解不同国家、交通与宗教情形，最终进入印度，在那烂陀等地研习佛学。他与当地学者交流，学习语言和论证方法，收集大量佛教文献。","645年回到长安后，他在朝廷支持下组织系统译经，分工包括译出、证义、缀文和校订等。由其见闻口述、辩机编次的《大唐西域记》，保存了沿途政区、习俗与佛教状况的重要资料。","大量经论被译为汉文，推动唯识学等学术发展，并为中国与南亚、中亚文化联系留下内容丰富的记载。","玄奘的贡献是求学、翻译、知识整理与跨文化沟通的结合。其行旅也说明唐代世界由多条政治和宗教网络连接，而非一个人进入无人之地；沿途居民、僧侣与统治者提供了重要帮助。","出发年份及生年有不同研究口径；《西游记》是后世小说，不是行程档案，《西域记》对不同地区也含亲见与转闻之别。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第112191—112193、112300—112430行；据相关正文综合概述，年代争议见正文"}]},
  "ann-cl-tang-690-44": {"heading":"专题连读 · 武则天建立周与唐复辟","paragraphs":["武则天由皇后进入最高决策层，高宗后期已参与国家政治。高宗去世后，围绕皇室、官僚和继承的斗争继续，她以皇太后身份控制政权，并逐渐为直接称帝创造条件。","武则天运用官员任免、科举选拔、政治宣传与宗教符号扩展支持，也严厉打击反对者。690年她称帝，改国号周，洛阳的政治地位进一步上升。","武周仍依靠既有国家制度和文官体系运作，同时调整人事、笼络新力量。告密与酷吏政治造成恐惧，部分官员受到冤枉；晚年权力集中于近侍，又引发新的宫廷危机。","705年政变迫使武则天退位，唐中宗复位，唐国号恢复。但武周时期提拔的官员和若干政治变化并未因此全部消失。","她是中国帝制史上极少见的正式女性皇帝，其地位不能只用性别传奇解释。评价应同时考察其政治能力、人才流动、国家延续与高压统治的代价，避免“女主必乱”或无条件赞颂两种极端。","传世史书对女性掌权常带性别与正统立场；关于宫闱私生活和具体案件的戏剧化细节，不宜无证据地填充生平。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第97900—98140行；据相关正文综合概述，年代争议见正文"}]},
  "ann-cl-tang-763-87": {"heading":"专题连读 · 安史之乱","paragraphs":["唐玄宗后期，边镇集聚兵力，内地与中央的军事配置相对薄弱。安禄山兼领重要军镇，与朝廷的矛盾又同宫廷政治、财政和指挥体系问题交织，形成叛乱条件。","755年安禄山起兵南下，攻取洛阳，次年潼关失守、长安陷落，玄宗西逃，肃宗在灵武即位。唐政府依靠朔方等军队和外部援兵组织反攻，战争因此牵涉更复杂的联盟与资源交换。","叛军内部先后发生安庆绪杀父、史思明夺权及史朝义继位等变化，唐军也经历收复两京、邺城失利与再度争夺。至763年史朝义败亡，主要叛军政权结束。","唐朝保住国号和中央朝廷，但河北部分降将获准保有军镇，战争破坏、军事地方化与财政困难并未随平乱自动消失。","安史之乱是唐代制度转变的重要节点，推动募兵、藩镇与财税调整，江淮财赋的重要性更加突出。它不是“盛唐瞬间变成亡国”的单线故事，之后唐仍延续一个多世纪并不断尝试恢复控制。","人口登记骤减不能全部解释为死亡；具体伤亡、部队数量与所谓固定“由盛转衰”年份均需审慎。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第98166—98240行；据相关正文综合概述，年代争议见正文"}]},
  "ann-cl-tang-875-121": {"heading":"专题连读 · 黄巢起义与晚唐战争","paragraphs":["唐后期财政征敛、灾荒、地方军政与社会流动问题交织。盐业及私盐活动与国家专卖之间的冲突，也为部分起义组织者提供网络，反抗并非只有单一粮食危机原因。","黄巢起兵后与王仙芝相关力量相互联系，又逐渐成为独立的重要领导者。其军长期转战，多次跨越不同地区，879年进入广州，随后转向北方。","广明元年冬攻入长安（传统编年列880年，公历已至881年初），黄巢建立政权，唐僖宗出逃。占有首都未能自动解决粮食、官僚合作与外部军事压力；唐廷借助地方军阀与沙陀等力量反攻，局面持续恶化。","884年黄巢败亡，其主要政权结束，但战争严重损害唐朝统治，朱温等在其中壮大，地方军事集团成为此后政治竞争的中心。","黄巢战争连接晚唐与五代：国家既依靠军阀平乱，又因军阀扩大而更加失去控制。理解其历史位置，须同时看反抗的社会背景、战争破坏及新权力结构的形成。","杀戮与人口损失的记载常含夸张或敌对书写，不能照录为精确数字；不把黄巢失败与唐朝正式灭亡写成同一年。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"提供合并本第108595、108625—108649行：南下、北征、长安与反攻"}]},
  "ann-cl-tang-879-123": {"heading":"专题连读 · 黄巢起义与晚唐战争","paragraphs":["唐后期财政征敛、灾荒、地方军政与社会流动问题交织。盐业及私盐活动与国家专卖之间的冲突，也为部分起义组织者提供网络，反抗并非只有单一粮食危机原因。","黄巢起兵后与王仙芝相关力量相互联系，又逐渐成为独立的重要领导者。其军长期转战，多次跨越不同地区，879年进入广州，随后转向北方。","广明元年冬攻入长安（传统编年列880年，公历已至881年初），黄巢建立政权，唐僖宗出逃。占有首都未能自动解决粮食、官僚合作与外部军事压力；唐廷借助地方军阀与沙陀等力量反攻，局面持续恶化。","884年黄巢败亡，其主要政权结束，但战争严重损害唐朝统治，朱温等在其中壮大，地方军事集团成为此后政治竞争的中心。","黄巢战争连接晚唐与五代：国家既依靠军阀平乱，又因军阀扩大而更加失去控制。理解其历史位置，须同时看反抗的社会背景、战争破坏及新权力结构的形成。","杀戮与人口损失的记载常含夸张或敌对书写，不能照录为精确数字；不把黄巢失败与唐朝正式灭亡写成同一年。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"提供合并本第108595、108625—108649行：南下、北征、长安与反攻"}]},
  "ann-cl-tang-880-124": {"heading":"专题连读 · 黄巢起义与晚唐战争","paragraphs":["唐后期财政征敛、灾荒、地方军政与社会流动问题交织。盐业及私盐活动与国家专卖之间的冲突，也为部分起义组织者提供网络，反抗并非只有单一粮食危机原因。","黄巢起兵后与王仙芝相关力量相互联系，又逐渐成为独立的重要领导者。其军长期转战，多次跨越不同地区，879年进入广州，随后转向北方。","广明元年冬攻入长安（传统编年列880年，公历已至881年初），黄巢建立政权，唐僖宗出逃。占有首都未能自动解决粮食、官僚合作与外部军事压力；唐廷借助地方军阀与沙陀等力量反攻，局面持续恶化。","884年黄巢败亡，其主要政权结束，但战争严重损害唐朝统治，朱温等在其中壮大，地方军事集团成为此后政治竞争的中心。","黄巢战争连接晚唐与五代：国家既依靠军阀平乱，又因军阀扩大而更加失去控制。理解其历史位置，须同时看反抗的社会背景、战争破坏及新权力结构的形成。","杀戮与人口损失的记载常含夸张或敌对书写，不能照录为精确数字；不把黄巢失败与唐朝正式灭亡写成同一年。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"提供合并本第108595、108625—108649行：南下、北征、长安与反攻"}]},
  "ann-cl-tang-884-126": {"heading":"专题连读 · 黄巢起义与晚唐战争","paragraphs":["唐后期财政征敛、灾荒、地方军政与社会流动问题交织。盐业及私盐活动与国家专卖之间的冲突，也为部分起义组织者提供网络，反抗并非只有单一粮食危机原因。","黄巢起兵后与王仙芝相关力量相互联系，又逐渐成为独立的重要领导者。其军长期转战，多次跨越不同地区，879年进入广州，随后转向北方。","广明元年冬攻入长安（传统编年列880年，公历已至881年初），黄巢建立政权，唐僖宗出逃。占有首都未能自动解决粮食、官僚合作与外部军事压力；唐廷借助地方军阀与沙陀等力量反攻，局面持续恶化。","884年黄巢败亡，其主要政权结束，但战争严重损害唐朝统治，朱温等在其中壮大，地方军事集团成为此后政治竞争的中心。","黄巢战争连接晚唐与五代：国家既依靠军阀平乱，又因军阀扩大而更加失去控制。理解其历史位置，须同时看反抗的社会背景、战争破坏及新权力结构的形成。","杀戮与人口损失的记载常含夸张或敌对书写，不能照录为精确数字；不把黄巢失败与唐朝正式灭亡写成同一年。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"提供合并本第108595、108625—108649行：南下、北征、长安与反攻"}]},
  "ann-cl-five-dynasties-959-179": {"heading":"专题连读 · 柴荣整顿后周与南北用兵","paragraphs":["五代中原政权更替频繁，军队拥立和地方割据削弱财政与秩序。柴荣继承郭威政权后，希望整顿军政、扩充资源，并在多国并存的局面中取得统一优势。","继位之初，柴荣在高平抵抗北汉及契丹援军，胜利后整顿禁军、重订军纪并选练精兵。他同时重视吏治、财政、水利与城市建设，使军事目标获得较稳定的资源基础。","根据王朴等人的战略建议，后周先后对后蜀与南唐用兵，从南唐取得淮南大片地区；959年北上又夺取部分州县。南北作战采取分步骤推进，而不是一次消灭所有对手。","后周国力增强、版图扩展，但柴荣于959年病逝，未能完成其计划。次年赵匡胤代周建宋，继承了相当部分军队、资源和政治条件。","柴荣是连接五代与北宋的重要人物，其整顿成果说明宋的统一并非凭空发生。理解其贡献，也须看到征战和限制佛教等措施对社会的不同影响，不能只依“雄主”形象作单向赞颂。","其统一战略的记述主要来自五代、宋代史籍，不能把后宋全部成就倒推为柴荣已经安排的结果。"],"references":[{"label":"《中国断代史系列·全集》用户提供整理本（先秦、秦汉、魏晋南北朝、隋唐五代相关正文）","note":"合并整理本第109770—109830行；据相关正文综合概述，年代争议见正文"}]},
  "ann-cl-song-liao-xia-jin-1114-260": {"heading":"专题连读 · 完颜阿骨打建立金朝","paragraphs":["完颜部在辽朝体系内逐步扩大势力，女真诸部受贡纳、征发和辽方干预。阿骨打继承部众整合成果，在与辽矛盾激化后转向公开军事反抗。","1114年阿骨打起兵，在宁江州、出河店等战斗取得胜利，增强部众信心。宗翰、吴乞买等推动其确立皇帝地位，以统一政治号令。","1115年阿骨打即位，建立金朝。新政权以猛安谋克等组织汇集人口和兵力，继续攻取辽的州城，逐渐由部族联盟转化为统治多种人口的国家。","金朝成立，辽在东北的统治受到根本挑战；此后金与宋结盟攻辽，1125年辽中央政权覆亡，北方力量格局重组。","金的兴起不仅是一次军事胜利，也涉及女真社会组织、辽朝边疆治理与多民族行政体系的变化。进入中原后，金的制度又不断调整，不能与建国初期视作同一状态。","女真建国叙事包含王朝正统化加工；军队数字、部落谱系与建国仪式须结合《金史》等材料的成书背景阅读。"],"references":[{"label":"中国断代史系列·辽金西夏史","note":"整理本第130979—130999行；第三章 辽朝衰亡与金朝建立，第二节 生女真与金朝"}]},
  "ann-cl-song-liao-xia-jin-1127-273": {"heading":"专题连读 · 靖康之变与北宋灭亡","paragraphs":["宋金联手灭辽后，双方因燕云交割、降将与边境控制发生冲突。辽的消失同时使宋直接面对金的军事力量，朝廷在防战与求和之间反复摇摆。","金军分路南下，围困太原并进逼开封。第一次围城后宋以赔款和割地等条件换取撤军，但防御组织与政治决策未能稳定，金军再度进攻。","第二次开封围城中，守军失利，城池陷落。金军控制徽宗、钦宗及宗室官员，索取大批财物人口，并于1127年将二帝等押送北方。","以开封为中心的北宋朝廷终结；赵构在南方另立朝廷，宋朝进入南宋阶段。北方各地仍有军民抵抗，并非都城陷落即使所有地方同时停止活动。","战争带来人口流动、经济破坏及政治中心南移，深刻改变后续宋金对峙。它也是理解南宋军事组织、财政重建和文化记忆的关键转折。","原书部分纪年有文字错置，本站以通行1125—1127年框架表述；复杂失败不能只归结为一位君主或一次城防失误。"],"references":[{"label":"中国断代史系列·宋史","note":"整理本第125489—125507行；第十章 北宋末年的腐朽统治及其灭亡，第三节 金灭北宋"}]},
  "ann-cl-song-liao-xia-jin-1279-337": {"heading":"专题连读 · 元军南下与南宋覆亡","paragraphs":["襄樊失守后，元军突破长江中游屏障，沿江东下。南宋中央财赋、军事协调与政治领导均处于危机，但各地的守城和抵抗并未同时结束。","1276年元军进入临安，宋恭帝及太后归降。陆秀夫、张世杰等护送宗室在东南沿海继续建立朝廷，文天祥则在江西、广东组织抵抗。","元军继续追击海上宋廷。1279年崖山战斗中，宋军水寨败溃，幼帝赵昺随陆秀夫投海，海上朝廷结束；文天祥此前已被俘，后在大都拒降就义。","南宋作为中央王朝终结，元朝完成对原南宋主要区域的征服。地方反抗与战争后续仍持续存在。","这次改朝换代带来统治组织及社会秩序重组，也留下遗民思想、忠义文学与深刻战争记忆。与此同时，许多地方文化和经济实践在元代继续发展，不能以王朝终结等同文明终结。","传统资料中的死亡人数差异很大；应强调惨烈性而不把缺乏可靠统计的巨额数字作为精确事实。"],"references":[{"label":"中国断代史系列·宋史","note":"整理本第126432—126454行；第十三章 南宋晚期的腐朽统治与元灭南宋，第二节 元灭南宋"}]},
  "ann-cl-yuan-1280-390": {"heading":"专题连读 · 郭守敬等编成《授时历》","paragraphs":["辽金旧历长期沿用后累积误差，南宋历法也有局限。统一后的元廷把制定共同历法视为国家治理与皇权名分的重要工作，集结多位历算人才。","王恂、许衡、郭守敬等参与修历。团队参考前代历法并安排跨地区观测，郭守敬改进简仪、高表等测量工具，强调以实际天象检验推算。","各地测验提供日影、纬度与天象资料，经过计算和校核形成《授时历》。这既依靠个人巧思，也依赖官署组织、工匠制作和地域网络。","新历于1280年完成，次年施行，回归年长度等推算达到较高水平，长期影响后世历法。","它表现出传统中国天文学在观测仪器、数学方法与制度组织上的成就，也说明技术史不能只列一个发明者而忽略合作过程。","提供书原文两处对设局年份表述不同，且将临安陷落前后混写；本站区分1276年组织修历与1280年完成，不沿用其中1275年已下临安的错误。"],"references":[{"label":"中国断代史系列·元史","note":"整理本第146543—146559行；第十三章 文 化，第五节 科学技术"}]},
  "ann-cl-yuan-1359-428": {"heading":"专题连读 · 治河危机与红巾军起义","paragraphs":["元后期财政和钞法紊乱，黄河水患与大规模征发加重民众负担。地方宗教、秘密结社及既有反抗网络，为起事者组织人众提供条件。","朝廷征集人力治河，刘福通等在颍州发动起义，借助宗教口号号召群众，队伍以红巾为标识。其他地区也陆续出现徐寿辉等建立的武装和政权。","起义军一度大规模北伐，但内部指挥、地方目标及资源状况不一。元廷调兵镇压的同时，地方军将权力上升，红巾体系中的朱元璋等又逐步发展为独立竞争者。","元朝对广大地区的控制瓦解，军事割据与新的权力重组加速，为明朝兴起创造条件。起义本身并未由单一领导连续统辖到建明。","应同时看到灾荒、征役、财政制度和宗教动员之间的关系，以及战争给普通人口造成的破坏，避免把元末仅叙述为几个英雄相互争霸。","石人一只眼等故事是政治动员与传说的重要材料，其具体制作情节需辨史源；不同红巾队伍也不宜全部合并为同质组织。"],"references":[{"label":"中国断代史系列·元史","note":"整理本第144978—145010行；第十二章 元末人民大起义，第一节 元末社会总危机的形成"}]},
  "ann-cl-ming-1380-445": {"heading":"专题连读 · 洪武制度与丞相废除","paragraphs":["建国后朱元璋逐渐担心功臣、宰相和地方长官集权，试图由皇帝直接掌握行政与军队。元代行省及中书省制度也在这一过程中被改造。","1380年胡惟庸被以谋反等罪处死，案件后来不断扩大牵连。朱元璋废中书省和丞相，由六部直接对皇帝负责，并调整大都督府等军事机构。","此前地方行省已被拆分为布政使司等系统，军政司法各有官署。皇帝通过法律、监察和特务机构加强控制，既整饬官吏，也造成政治恐惧。","中国延续多朝的宰相制度在明朝被正式废除，中央行政的最终决策与大量具体事务更加集中于君主。","此后内阁逐步承担拟旨协调工作，却不等同恢复旧式丞相。制度增加君主工作负担，也使辅政、宦官与皇权之间形成新的关系。","胡惟庸案的谋反指控、牵连范围和后期追认包含政治性加工，不能把官方罪名全部当作已经独立证实的事实。"],"references":[{"label":"中国断代史系列·明史（上、下）","note":"整理本第149065—149109行；第二章 明初全国统一的完成明太祖的治国政策，第二节 加强君主专制统治的政治制度"}]},
  "ann-cl-ming-1399-465": {"heading":"专题连读 · 靖难之役与朱棣夺位","paragraphs":["建文帝继位后试图削弱诸藩军政力量，燕王朱棣拥有北方军队与边防经验。中央与藩王对权力分配的冲突迅速发展为内战。","1399年朱棣以清君侧、靖难为名起兵，控制北平并与朝廷军队反复交战。战争中既有坚城防守，也有绕道突进，地方兵源和运输承担巨大压力。","朱棣最终避开部分坚城，沿运河方向南下，于1402年攻入南京并即位，改次年为永乐。建文旧臣受到清洗，建文朝制度和历史记述也被重新处理。","皇位由侄转叔，削藩引发的内战以燕王胜利结束。朱棣即位后继续限制其他藩王，显示其胜利并非恢复诸藩普遍自治。","这一事件改变明初权力结构，为迁都北京、北征和远航等永乐事业提供政治背景，也留下战争损失与正统争议。","建文帝最终下落缺乏一致可靠证据；出家、出海等传说可作文化记忆介绍，不应作为已证实人生经历。"],"references":[{"label":"中国断代史系列·明史（上、下）","note":"整理本第149744—149856行；第三章 从永乐到宣德治国政策的演变，"}]},
  "ann-cl-ming-1405-469": {"heading":"专题连读 · 郑和七次远航","paragraphs":["明成祖在国内夺位之后扩大对外联系，既希望展示王朝威望、发展朝贡关系，也搜集海外信息和取得物资。此前印度洋已有多方商人与港口网络。","郑和、王景弘等组织官军船队，经过东南亚重要港口，抵达印度洋沿岸若干国家。船队进行使节往来、赏赐与交易，也参与海盗、港口政争和军事冲突。","航行依赖季风、导航经验、造船、补给和译员。1431年所铸祈愿铜钟等实物可与碑铭、随行者见闻互证，说明航海并非只有后世传奇。","明与沿途政治实体建立或加强联系，带回使节、物产和知识。大型国家船队后来停止，并不意味着中国民间海上贸易就此完全中断。","这些航行是观察中国与印度洋世界交往的重要窗口。应同时呈现海港社会、当地自主力量及航行成本，避免将海外居民仅写成接受中国赏赐的背景。","宝船尺寸、总人数及最远航路部分细节仍有研究分歧；没有可靠证据支持其环球航行等夸张说法。郑和卒年常记1433，也有异说。"],"references":[{"label":"中国断代史系列·明史（上、下）","note":"整理本第150965—151018行；第六章 明初的中外关系和郑和远航亚非各国，"},{"label":"航海家——郑和","url":"https://www.igsnrr.cas.cn/cbkx/kpyd/dlxj/202009/t20200910_5692679.html","note":"七次远航年份及地理范围段。大型宝船尺寸有争议，本站未采用其数字。"}]},
  "ann-cl-ming-1418-480": {"heading":"专题连读 · 郑和七次远航","paragraphs":["明成祖在国内夺位之后扩大对外联系，既希望展示王朝威望、发展朝贡关系，也搜集海外信息和取得物资。此前印度洋已有多方商人与港口网络。","郑和、王景弘等组织官军船队，经过东南亚重要港口，抵达印度洋沿岸若干国家。船队进行使节往来、赏赐与交易，也参与海盗、港口政争和军事冲突。","航行依赖季风、导航经验、造船、补给和译员。1431年所铸祈愿铜钟等实物可与碑铭、随行者见闻互证，说明航海并非只有后世传奇。","明与沿途政治实体建立或加强联系，带回使节、物产和知识。大型国家船队后来停止，并不意味着中国民间海上贸易就此完全中断。","这些航行是观察中国与印度洋世界交往的重要窗口。应同时呈现海港社会、当地自主力量及航行成本，避免将海外居民仅写成接受中国赏赐的背景。","宝船尺寸、总人数及最远航路部分细节仍有研究分歧；没有可靠证据支持其环球航行等夸张说法。郑和卒年常记1433，也有异说。"],"references":[{"label":"中国断代史系列·明史（上、下）","note":"整理本第150965—151018行；第六章 明初的中外关系和郑和远航亚非各国，"},{"label":"航海家——郑和","url":"https://www.igsnrr.cas.cn/cbkx/kpyd/dlxj/202009/t20200910_5692679.html","note":"七次远航年份及地理范围段。大型宝船尺寸有争议，本站未采用其数字。"}]},
  "ann-cl-ming-1431-492": {"heading":"专题连读 · 郑和七次远航","paragraphs":["明成祖在国内夺位之后扩大对外联系，既希望展示王朝威望、发展朝贡关系，也搜集海外信息和取得物资。此前印度洋已有多方商人与港口网络。","郑和、王景弘等组织官军船队，经过东南亚重要港口，抵达印度洋沿岸若干国家。船队进行使节往来、赏赐与交易，也参与海盗、港口政争和军事冲突。","航行依赖季风、导航经验、造船、补给和译员。1431年所铸祈愿铜钟等实物可与碑铭、随行者见闻互证，说明航海并非只有后世传奇。","明与沿途政治实体建立或加强联系，带回使节、物产和知识。大型国家船队后来停止，并不意味着中国民间海上贸易就此完全中断。","这些航行是观察中国与印度洋世界交往的重要窗口。应同时呈现海港社会、当地自主力量及航行成本，避免将海外居民仅写成接受中国赏赐的背景。","宝船尺寸、总人数及最远航路部分细节仍有研究分歧；没有可靠证据支持其环球航行等夸张说法。郑和卒年常记1433，也有异说。"],"references":[{"label":"中国断代史系列·明史（上、下）","note":"整理本第150965—151018行；第六章 明初的中外关系和郑和远航亚非各国，"},{"label":"航海家——郑和","url":"https://www.igsnrr.cas.cn/cbkx/kpyd/dlxj/202009/t20200910_5692679.html","note":"七次远航年份及地理范围段。大型宝船尺寸有争议，本站未采用其数字。"}]},
  "ann-cl-qing-1678-664": {"heading":"专题连读 · 三藩战争","paragraphs":["清初借助吴三桂、尚可喜、耿氏等汉人降将控制南方，授予藩镇广泛军政权力和巨大财政供给。随着统治稳定，朝廷担心藩镇形成独立权力。","康熙接受撤藩请求并决定逐步收回藩权，吴三桂于1673年起兵，耿精忠等相继响应。叛军一度控制大片地区，沿江和西南成为主要战场。","清廷一面集中军队，一面分化各路势力，部分响应者先后投降。吴三桂称帝后不久去世，其孙吴世璠继续抵抗，1681年昆明被攻克。","清廷消灭主要南方藩镇，收回广泛军事与财赋权力。战争持续八年，对人口、农业与地方财政造成严重损失。","事件显示清初中央集权依赖从军事合作向直接官僚管理的转变，也为随后解决沿海郑氏政权提供条件。应同时看到国家整合与战争负担。","三藩并非三位同等行动、同时起兵的个人，各藩内部及不同时期态度差异很大，不能用一个整齐集团概括。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第174781—174857行；第六章 康熙时期的政治斗争与经济恢复，第一节 康熙时期的政治斗争"}]},
  "ann-cl-qing-1689-673": {"heading":"专题连读 · 雅克萨战争与尼布楚条约","paragraphs":["俄国势力向西伯利亚和黑龙江流域扩展，与清朝在当地人口、贡纳及据点控制上发生冲突。俄方在雅克萨筑垒，清廷则试图排除该军事据点。","清军于1685年进攻雅克萨，俄军撤出后重新筑守，1686年再次遭围。作战之外，双方逐步认可通过外交划定势力范围，以减轻远距离补给和多线防务压力。","1689年双方代表在尼布楚谈判，利用翻译和拉丁文等文本形成条约，规定有关边界与撤除据点等事项，并处理逃人和贸易问题。","雅克萨冲突以条约安排结束，清俄东段边界形成重要法律依据，相关地区获得较长时期相对稳定。","这是清朝与欧洲国家正式条约外交的重要案例，展示军事力量、边疆知识和跨语言交涉如何共同塑造边界，而不是单方面凭一张地图完成。","条约不同语言文本、地名及未定区域须分别辨认；不能把1689年条约直接等同今天全部中俄边界。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第175445—175473行；第七章 清初经营边疆和巩固统一的战争，第一节 抗击沙俄对黑龙江流域的入侵和尼布楚条约的签订"}]},
  "ann-cl-qing-1723-689": {"heading":"专题连读 · 永不加赋与摊丁入亩","paragraphs":["人丁税以编审人口为征税依据，人口流动、隐漏与负担不均使征收困难。清初恢复生产后，统治者希望稳定税额，减少编审纠纷并保证财政。","康熙于1712年宣布以既定丁数为常额，后续滋生人口不再加征。该政策固定国家丁银收入，但并非立即取消原来各户承担的丁税。","雍正时朝廷支持将丁银逐步按田亩摊入地税，吸收地方已有试验。实施办法和时间各省不同，清丈、税额及地方附加仍会影响实际负担。","征税基础由单独的人丁项目更多转向土地，部分无地少地人口负担减轻，人口登记与征税的直接联系减弱。","这是赋役货币化与税基调整的延续，有利于理解清代人口统计、土地占有和财政制度。它不意味着农民从此没有额外征派，更不等于现代意义的全部人头税绝对消失。","永不加赋是针对固定丁额的新生人丁，不是承诺任何财政项目永不增加；不同地区丁银入地的具体比例需分别说明。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第176125—176149行；第八章 雍正时期的政治和经济，第二节 赋役制度的改革"}]},
  "ann-cl-qing-1842-748": {"heading":"专题连读 · 虎门销烟与鸦片战争","paragraphs":["英国对华鸦片贸易造成白银、社会与政治问题，清廷禁烟与英国商贸扩张发生尖锐冲突。工业化海军和清朝沿海防务之间存在明显装备与组织差距。","林则徐到广州收缴鸦片并在虎门销毁。英国政府以此等事为由发动战争，舰队沿海北上，以封锁、占城和军事威胁迫使清廷谈判。","清廷多次更换主事官员，抵抗与求和政策摇摆；英军后来进入长江、攻取镇江，威胁南京及运河财赋通道，使清廷面临更大压力。","1842年签《南京条约》，割让香港岛、赔款、开放五口，并确立协定关税相关原则；1843年附约又加入治外法权等安排。","中国与西方列强的关系进入条约体系新阶段，主权、海贸与社会秩序受到深刻影响。战争同时促使部分士人搜集世界知识，反思军备和治理。","不可把条约所有后续特权都写成《南京条约》同一文本条款；禁烟是战争直接导火线，不能代替对商业利益与帝国扩张的深层分析。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第180013—180259行；第一章 道光朝后期社会的新变动，第一节 鸦片战争"},{"label":"中国断代史系列·清史（上、下）","note":"整理本第180433—180507行；第一章 道光朝后期社会的新变动，第三节 思想界的新动向 ——从“夷夏之防”到“师夷长技”的历史转变"}]},
  "ann-cl-qing-1851-753": {"heading":"专题连读 · 太平天国兴起与战争","paragraphs":["人口压力、土地及财政负担、地方族群冲突和灾害，使华南部分社会动荡。洪秀全等将基督教材料重新解释为拜上帝信仰，形成独特的宗教与政治动员。","1851年金田起义后，太平军突破清军封锁北上，1853年占领南京，改称天京。此后展开北伐、西征并在长江流域建立统治，与清军长期争夺城市和粮道。","1856年天京内部冲突严重削弱领导层。清廷依靠湘军、淮军等地方武装及部分外国力量反攻；太平天国也调整战略，尝试建设与新的政治方案。","1864年天京陷落，洪秀全此前去世，主要政权结束。多年战争给广大地区造成巨大人口与经济损失，清朝也因此更依赖地方军政网络。","其反抗旧秩序、宗教理想、土地方案与实际等级统治之间存在明显张力。它既影响近代政治思想，又改变地方权力和洋务发展的环境。","《天朝田亩制度》是政治纲领，不能描述为已在所有占领区平均分田的实际制度；战争死亡人数的精确估计有很大争议。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第181009—181285行；第二章 咸丰朝之内忧与外患（上），第四节 太平天国的兴起与发展"},{"label":"中国断代史系列·清史（上、下）","note":"整理本第182273—182395行；第四章 同治中兴（上），第三节 太平天国灭亡与各地起义平息"}]},
  "ann-cl-qing-1895-820": {"heading":"专题连读 · 甲午战争与《马关条约》","paragraphs":["日本扩军与对朝鲜的控制企图同清朝的宗藩秩序发生冲突。朝鲜东学党起义使双方出兵，日军随后控制朝鲜王宫并扩大军事行动。","1894年丰岛、平壤与黄海等战事相继发生，清军在朝鲜陆战失利，北洋海军受损。日军进一步攻入辽东，战争延伸到中国本土。","1895年威海卫陷落，北洋舰队覆没。李鸿章等赴日谈判，在军事压力下签订《马关条约》，包括赔款、割让台湾澎湖等、增开口岸和准许日商设厂等条款。","清朝战败，东亚国际关系重组，台湾进入日本殖民统治；辽东因俄德法干涉被赎回，但列强争夺进一步加剧。","失败冲击洋务成果与王朝威信，刺激维新、革命和实业救国思潮。战败原因涉及战略指挥、财政、组织与军队建设，不宜只用舰炮新旧解释。","不能把北洋舰队的覆没等同中国全部海军同日消失，也不能把辽东最终处理同条约最初割让条款混为一谈。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第184279—184451行；第六章 光绪朝社会的急剧变化与重大变革（上），第四节 中日甲午战争"}]},
  "ann-cl-qing-1898-828": {"heading":"专题连读 · 戊戌变法与政变","paragraphs":["甲午战败与列强争夺加剧民族危机，维新者通过报刊、学会和上书传播变法主张。光绪帝希望推进改革，但皇权受慈禧及既有官僚网络牵制。","光绪发布明定国是诏后，改革涉及科举教育、工商、军事和行政，康有为、梁启超等进入政策讨论网络。京师大学堂等事业开始筹办。","密集诏令触动官僚利益，改革派缺乏稳定组织、军权和地方执行基础。9月慈禧重新控制朝政，光绪被幽禁，谭嗣同等六人被杀，多项政策撤销。","以皇帝为中心的短期政治改革失败，主要参与者流亡或转入其他活动；部分教育机构与知识传播成果仍保留下来。","变法使制度改革成为全国政治议题，并影响后来的清末新政及革命讨论。它既有思想解放作用，也体现在权力、群众基础和施行次序方面的局限。","公车上书的实际递交方式、围园杀后等政治情节有史源争议；不要把康有为后来的自述全部当成同时期可靠记录。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第185107—185253行；第八章 光绪朝社会的急剧变化与重大变革（下），第二节 戊戌变法"}]},
  "ann-cl-qing-1901-833": {"heading":"专题连读 · 义和团、联军入侵与辛丑条约","paragraphs":["列强侵略和部分教案特权加剧乡村矛盾，灾害与生计压力推动民间拳会发展。信仰、反洋情绪与地方权力冲突交织，义和团迅速扩散。","义和团攻击教堂、外来人员及中国基督徒，毁坏铁路等设施。清廷对其先抑后扶，部分官员试图借团民抗击列强，使冲突由地方暴力演变为重大外交危机。","八国联军出兵，攻取天津、北京，宫廷西逃。战争伴随杀戮、抢掠与报复，北方居民遭受严重伤害；东南督抚则选择同列强维持互保安排。","1901年《辛丑条约》规定巨额赔款、驻兵及处罚等内容，清朝主权进一步受损，朝廷转入规模更大的新政。","事件必须同时呈现反侵略诉求、排外暴力、清廷失策及联军侵略责任；不能将任何一方无辜平民的死亡合理化。","神拳不惧枪炮是当时信仰与动员话语，不是事实能力；义和团内部、官员与各地区的立场也不完全一致。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第185255—185439行；第八章 光绪朝社会的急剧变化与重大变革（下），第三节 义和团运动"}]},
  "ann-cl-qing-1912-859": {"heading":"专题连读 · 辛亥革命与清帝退位","paragraphs":["新政、预备立宪与革命组织同时发展，皇族内阁、铁路国有与保路风潮加剧清廷合法性危机。湖北新军中的革命团体已积累组织基础。","武昌起义成功后，各省先后宣布独立，建立军政府；清廷起用袁世凯，北洋军与革命军作战，同时南北代表展开谈判，军事与政治妥协相互推动。","1912年1月1日南京临时政府成立，孙中山任临时大总统。围绕共和国体、清室待遇和总统职位，南北继续协商；2月12日隆裕太后以宣统帝名义颁布退位诏书。","清朝统治结束，君主制度被共和政体取代；但军权、地方割据、社会改革和列强权益等问题没有因此解决。","革命显著改变政治合法性的语言与国家制度，推动共和国观念传播。其成果与局限都需放在后续政治实践中考察，不能用一日退位概括复杂的长期转型。","孙中山没有亲自在武昌指挥起义；清帝退位与民国成立日期不同，1911年和1912年应分列，不将所有节点合并。"],"references":[{"label":"中国断代史系列·清史（上、下）","note":"整理本第186693—186825行；第十章 宣统朝之穷途末路，第四节 辛亥革命高潮与清王朝灭亡"}]},
  "ann-chron-world-south-asia-0653": {"heading":"专题连读 · 阿育王敕令与统治转向","paragraphs":["孔雀王朝已建立幅员辽阔的国家。进一步扩张把迦陵伽纳入战争，军事控制与治理多种社群的难题同时凸显。阿育王的铭文是观察这种统治语言的重要同期材料，其地位不同于后世佛教传说。","迦陵伽征服造成大量伤亡、迁徙和家庭破坏。敕令把这场战争与国王的悔恨相联系，说明王权开始强调以道德劝导而非持续军事胜利塑造理想统治形象。","国王在岩壁与石柱上发布训令，针对不同地域采用不同文字或语言环境。内容涉及伦理、宗教社群相处和臣民行为；佛教得到支持，但王朝的公共伦理不能完全等同某一部佛经。","阿育王统治留下分布广泛的铭文与建筑传统，使其道德政治表达有了可见载体；国家本身仍保有行政与强制能力。","佛塔、巡礼与佛教传播得到王权支持，阿育王后来成为南亚和佛教世界反复援引的理想君主。铭文也为现代研究孔雀国家与古印度文字提供核心材料。","不宜写成战争后立刻彻底放弃一切武力；转向有持续过程。某次结集和传教使团的细节应注明不同传承，不能把后世传说一律当同期记载。"],"references":[{"label":"South Asia, 1000 B.C.–1 A.D.","url":"https://82nd-and-fifth.metmuseum.org/toah/ht/04/ssa.html","note":"前260年迦陵伽征服、佛教支持及孔雀时代佛塔的年表与概述。"}]},
  "ann-chron-world-south-asia-0655": {"heading":"专题连读 · 阿育王敕令与统治转向","paragraphs":["孔雀王朝已建立幅员辽阔的国家。进一步扩张把迦陵伽纳入战争，军事控制与治理多种社群的难题同时凸显。阿育王的铭文是观察这种统治语言的重要同期材料，其地位不同于后世佛教传说。","迦陵伽征服造成大量伤亡、迁徙和家庭破坏。敕令把这场战争与国王的悔恨相联系，说明王权开始强调以道德劝导而非持续军事胜利塑造理想统治形象。","国王在岩壁与石柱上发布训令，针对不同地域采用不同文字或语言环境。内容涉及伦理、宗教社群相处和臣民行为；佛教得到支持，但王朝的公共伦理不能完全等同某一部佛经。","阿育王统治留下分布广泛的铭文与建筑传统，使其道德政治表达有了可见载体；国家本身仍保有行政与强制能力。","佛塔、巡礼与佛教传播得到王权支持，阿育王后来成为南亚和佛教世界反复援引的理想君主。铭文也为现代研究孔雀国家与古印度文字提供核心材料。","不宜写成战争后立刻彻底放弃一切武力；转向有持续过程。某次结集和传教使团的细节应注明不同传承，不能把后世传说一律当同期记载。"],"references":[{"label":"South Asia, 1000 B.C.–1 A.D.","url":"https://82nd-and-fifth.metmuseum.org/toah/ht/04/ssa.html","note":"前260年迦陵伽征服、佛教支持及孔雀时代佛塔的年表与概述。"}]},
  "ann-chron-world-africa-0910": {"heading":"专题连读 · 马里兴起与曼萨·穆萨朝觐","paragraphs":["西非拥有长期城市、农业、工艺和贸易传统，马里并非因欧洲地图记载才出现。黄金与商路提供王权资源，伊斯兰学者和朝觐网络使地区政治与更广世界相连。","马里王权连接多个城镇、地方精英与贸易路线，政治结构不能简单按现代边界重画。宗教信仰和地方传统并存，城市生活并不只有王室活动。","曼萨·穆萨远赴麦加，财富与随行队伍引起外界关注。返国后的宗教营建与知识赞助加强廷巴克图、加奥等地的联系，欧洲制图者又以持金君王表现其声望。","马里在地中海及伊斯兰地理知识中取得更显著地位，宗教和城市文化继续发展。","这条主线揭示西非在全球历史中的主动角色，可以与元朝欧亚通道、印度洋港市等同期阅读；贸易、信仰和艺术相互联系而非相互替代。","现代财富榜无法可靠计算穆萨资产；地图图像是欧洲表现方式，不是其真实肖像。王朝疆域、继承与时间数字仍须容许史料差异。"],"references":[{"label":"Visualizing a Sahelian Past","url":"https://www.metmuseum.org/it/perspectives/visualizing-a-sahelian-past","note":"Malian Emperor Mansa Musa小节支持穆萨、朝觐、宗教营建和地图形象；马里13世纪兴起沿用本站原框架，不以本专题证明具体建国年。"}]},
  "ann-chron-world-east-asia-0583": {"heading":"专题连读 · 德川幕府与江户秩序","paragraphs":["经历长期战国竞争，德川需要控制仍有资源与军队的大名，同时维持天皇和朝廷的象征作用。新秩序不是取消一切地方权力，而是把地方统治纳入更严密的等级和约束关系。","家康凭战争胜利和政治联盟在江户设立幕府，将军与大名形成多层统治结构。早期安排在其后继者时期继续调整，不能把全部制度都归为1603年当年完成。","战争趋缓，江户等城市增长，武士、商人、工匠和宗教机构形成新的消费与艺术环境。桃山时期的赞助和工艺延续，又在较稳定秩序中产生新表达。","出现持续两个多世纪的武家统治体系，地方战争明显减少，但社会身份、经济负担和政治参与仍不平等。","江户时代的出版、都市文化和工艺与这一政治环境相关；统治稳定并非社会静止，地方市场和普通人的文化活动不断改变生活。","“闭关锁国”不可概括全部江户史。早期建立、后来对外限制和幕末开放有各自年代；日本仍通过不同渠道与周边及欧洲往来。"],"references":[{"label":"Momoyama Period (1573–1615)","url":"https://www.metmuseum.org/fr/essays/momoyama-period-1573-1615","note":"专题家康统一与1603幕府背景、桃山结束及早17世纪艺术；后续制度在本条以过程而非单年说明。"}]},
  "ann-chron-world-central-west-asia-0386": {"heading":"专题连读 · 阿拔斯革命与巴格达建城","paragraphs":["倭马亚后期，不同政治、宗教和族群利益形成反对力量。阿拔斯家族以新的王朝合法性聚合支持者；政权变化同时改变帝国资源和行政中心的地理位置。","750年阿拔斯取得哈里发政权，帝国政治文化重心由叙利亚转向伊拉克。新王朝并不是消除所有差异的社会革命，军事和官僚结构仍需持续整合。","762年创建巴格达，圆城形制与“和平之城”的名称展示规划与王权理想。它依靠交通、水运和行政需求发展成庞大的文化商业中心，之后又有一段迁都萨迈拉的时期。","巴格达成为阿拔斯国家的核心，伊拉克在伊斯兰世界的政治、商业与艺术活动中取得突出地位。","新都及宫廷赞助促成跨地区工匠、商人和学者往来。阿拔斯艺术中的装饰、陶瓷与建筑形式传播广泛，显示政治中心如何影响文化生产。","王朝延续至1258年，不等于哈里发数百年都具有同样强的实际控制。巴格达遗存较少，认识建筑时应结合萨迈拉考古与文字材料，不能把理想规划等同全部城市。"],"references":[{"label":"The Art of the Abbasid Period (750–1258)","url":"https://www.metmuseum.org/it/essays/the-art-of-the-abbasid-period-750-1258","note":"首段750年更替、762年圆城和836—892年萨迈拉；文化商业中心与遗存限制。"}]},
  "ann-cl-yuan-1258-375": {"heading":"专题连读 · 蒙古攻陷巴格达","paragraphs":["蒙哥时期蒙古向西亚继续扩张，旭烈兀受命率大军西行，先处理伊朗地区的反对力量，再要求当地统治者臣服。阿拔斯哈里发仍具象征权威，但军事和地区支持不足。","蒙古军队从不同方向向巴格达集中，攻城和野战迫使城市迅速失去防御能力。哈里发与城市精英未能组织足够抵抗，投降后也未能保全王朝。","城破伴随大规模杀戮与破坏，哈里发被杀，巴格达的阿拔斯政治中心终结。蒙古统治随后在伊朗和两河形成伊儿汗国的政权基础。","巴格达遭受严重人口、建筑和制度损失，西亚权力格局发生变化；此后蒙古与埃及马穆鲁克等继续竞争。","事件是中世纪城市战争与帝国征服的重大灾难，也提醒人们不能仅以贸易交流描述蒙古扩张。后来的伊儿汗文化和科学活动则说明地区知识生活并未在1258年全部永久停止。","伤亡数字各史家差异很大，本文不写无法确证的总数。“全世界科学因此终结”及河水被所有藏书染黑等传说，不能无辨别照搬。"],"references":[{"label":"HULĀGU KHAN","url":"https://www.iranicaonline.org/articles/hulagu-khan/","note":"旭烈兀传记1257年末集结、1258年攻城、哈里发被杀与伊儿汗国统治段。"}]},
  "ann-chron-world-europe-0061": {"heading":"专题连读 · 奥古斯都与元首制","paragraphs":["共和国后期军队、财富和个人政治联盟不断结合，内战破坏了传统竞争机制。屋大维在凯撒遇刺后的权力斗争中胜出，需要让军事独占转化为被精英接受的长期统治。","他保留元老院、官职和公共仪式，用“首席公民”的位置集中军队和政治权威。元首制并非简单宣布取消共和国，而是使传统形式与实际个人统治并存。","城市建设、宗教仪式、肖像与文学赞助共同塑造秩序恢复的形象。和平祭坛、祈祷和祭祀姿态的雕像，把统治者与家族连接到罗马的宗教和历史使命。","罗马形成持续的皇帝统治框架；内战后较稳定的政局与个人权力集中相伴存在。元首制也留下继承问题，无法完全由既有共和程序解决。","政治与艺术密切结合成为帝国的重要特征。公共空间中的建筑、钱币和诗歌并非纯粹装饰，而参与讲述谁有权统治、何种过去值得纪念。","所谓“罗马和平”不能解释为帝国境内外没有战争，也不意味着被征服者与公民平等。史料中的恢复传统语言，须与真实权力结构对读。"],"references":[{"label":"Augustan Rule (27 B.C.–14 A.D.)","url":"https://www.metmuseum.org/de/essays/augustan-rule-27-b-c-14-a-d","note":"正文文学赞助、宗教身份、和平祭坛及视觉政治；参照元首统治背景。"}]},
  "ann-chron-world-europe-0296": {"heading":"专题连读 · 柏林会议与瓜分非洲","paragraphs":["19世纪后期欧洲列强加紧非洲扩张，贸易路线、国家竞争与殖民利益发生交叉。与会者试图用外交安排避免彼此冲突，却没有让非洲社会平等参与决定自身政治命运。","会议由俾斯麦主持召集，欧洲国家及美国代表参与。讨论以贸易和航行为重要名义，把非洲地域作为国际竞争和条约规范的对象。","最终文件规定刚果地区贸易、刚果河与尼日尔河航行等问题，并涉及今后占领和通知的原则。文件也使用反对奴隶贸易等语言，但这些承诺并不能证明殖民统治具有平等或人道性质。","会议给列强竞争提供一套规则与外交依据，殖民扩张继续加速；非洲各政体仍以外交、武装或其他方式应对外来压力。","它象征帝国主义者排除非洲主体的国际秩序，也有助于认识“文明”“自由贸易”等说辞怎样与资源支配并存。其后实际殖民边界仍在战争和另外的协定中逐步形成。","会议没有在一张地图上一次划定今天非洲全部国界。需区分1884—1885年会议、后续瓜分过程与各地区实际被征服的年代。"],"references":[{"label":"General Act of the Berlin West Africa Conference, 26 February 1885","url":"https://archiv.diplo.de/arc-en/the-political-archive/general-act-2684414","note":"档案介绍中的会议起止、总议定书主题与其殖民政策背景；以殖民档案视角作批判阅读。"}]},
  "ann-chron-world-africa-0956": {"heading":"专题连读 · 柏林会议与瓜分非洲","paragraphs":["19世纪后期欧洲列强加紧非洲扩张，贸易路线、国家竞争与殖民利益发生交叉。与会者试图用外交安排避免彼此冲突，却没有让非洲社会平等参与决定自身政治命运。","会议由俾斯麦主持召集，欧洲国家及美国代表参与。讨论以贸易和航行为重要名义，把非洲地域作为国际竞争和条约规范的对象。","最终文件规定刚果地区贸易、刚果河与尼日尔河航行等问题，并涉及今后占领和通知的原则。文件也使用反对奴隶贸易等语言，但这些承诺并不能证明殖民统治具有平等或人道性质。","会议给列强竞争提供一套规则与外交依据，殖民扩张继续加速；非洲各政体仍以外交、武装或其他方式应对外来压力。","它象征帝国主义者排除非洲主体的国际秩序，也有助于认识“文明”“自由贸易”等说辞怎样与资源支配并存。其后实际殖民边界仍在战争和另外的协定中逐步形成。","会议没有在一张地图上一次划定今天非洲全部国界。需区分1884—1885年会议、后续瓜分过程与各地区实际被征服的年代。"],"references":[{"label":"General Act of the Berlin West Africa Conference, 26 February 1885","url":"https://archiv.diplo.de/arc-en/the-political-archive/general-act-2684414","note":"档案介绍中的会议起止、总议定书主题与其殖民政策背景；以殖民档案视角作批判阅读。"}]},
  "ann-chron-world-americas-1042": {"heading":"专题连读 · 美国宪法与联邦政府","paragraphs":["独立后的邦联政府难以协调贸易、财政与各州关系，政治精英要求重新安排中央权力。1787年会议原本以修改《邦联条例》为任务，但很快转向起草新的国家宪制。","代表讨论中央和州、大小州、行政与立法之间的权力。两院制、总统及司法等安排逐渐成形，奴隶制相关妥协也写入制度，限制了权利原则的适用。","文本于1787年9月签署，各州围绕中央过强和缺少权利保障激烈争论。批准达到门槛后新政府运作，《权利法案》作为后续修正回应部分批评。","形成具有更具体职权的联邦政府，建立国会、总统和法院之间的组织框架；许多实际运行规则仍须由之后的法律、争执与判例发展。","该宪法成为后世成文宪政的重要参照，同时其历史也反映通过修正和政治斗争改变原有排除。稳定文本与持续变化的权利范围并存。","1787年签署并不等于全国当即生效；最初文本也不等于今天所有修正案。原住民、被奴役者与妇女的地位，不能用“人民”一词自动涵盖。"],"references":[{"label":"Constitution of the United States (1787)","url":"https://www.archives.gov/milestone-documents/constitution","note":"国家档案馆1787年制宪文件介绍、会议原目的与签署日期；批准和新政府背景。"}]},
  "ann-chron-world-americas-1048": {"heading":"专题连读 · 海地革命与废奴独立","paragraphs":["殖民地种植园依赖被奴役的非洲人及其后代，社会存在极端暴力和身份不平等。法国革命打开公民权讨论，但自由有色人、白人殖民者与被奴役者的目标并不相同。","1791年起义扩大后，革命力量在法国、西班牙和英国之间复杂周旋。杜桑·卢维杜尔逐渐成为重要领袖，军事组织与废奴诉求共同改变地方权力格局。","法国废奴后，杜桑在法国名义下扩大自治；1802年远征军到来，他遭拘押送往法国并死于囚禁。其后革命军继续抗击法军，最后由其他领袖完成独立。","海地摆脱法国殖民统治，奴隶制未能在当地恢复；新国家成立并不意味着经济压力、政治分裂和外部敌意就此消失。","革命使被奴役者成为争取普遍自由的主动政治力量，对大西洋世界的奴隶制与殖民秩序形成冲击。它应与美国、法国革命并列观察，而不是作为后两者的附属回声。","不能把全部起义和独立归功于单一领袖，也不应称杜桑为1804年独立时的国家元首。不同阶段的劳动政策、军事统治及内部冲突仍须分别评价。"],"references":[{"label":"Toussaint Louverture","url":"https://nmaahc.si.edu/latinx/toussaint-louverture","note":"博物馆人物条目关于被奴役出身、革命、政治领导、被俘与死亡；独立须区分杜桑去世之后的阶段。"}]},
  "ann-chron-world-oceania-1145": {"heading":"专题连读 · 怀唐伊条约与主权争议","paragraphs":["英国商人、传教士与移民增加，毛利各社群寻求应对贸易和土地压力的方式。英国则企图建立殖民治理；双方对保护、权威和土地交易的预期并不完全相同。","英国代表与部分毛利首领签订条约。毛利文与英文在关键政治概念上存在差异，尤其涉及治理权、主权与首领权威；绝大多数首领签的是毛利文本。","条约涉及王室治理、毛利对土地及其他珍贵资源的权利和臣民地位。英国随后宣称主权，但土地占有、战争和政府行为引起持续争议，不少承诺未被充分履行。","成为新西兰政治关系的重要基础文书，也成为毛利社群要求落实权利和追究违约的核心依据；并非所有社群都签署或作同样理解。","它显示跨语言条约不能只读一个版本。对照原文、签署情境与后来执行，有助于理解殖民治理如何改变土地、权力和国家叙事。","“毛利人整体自愿放弃全部主权”的表述过于简单。条约的历史解释和当代法律适用须区分，且应明确不同群体与时期的立场。"],"references":[{"label":"The Treaty in brief","url":"https://nzhistory.govt.nz/politics/treaty/the-treaty-in-brief","note":"The Treaty in brief：签署、英文与毛利文差异、权利义务及条约地位。"}]}
};
